        }

        case value_t::object:
        {
            // delegate call to object_t::max_size()
            return m_data.m_value.object->max_size();
        }

        case value_t::null:
        case value_t::string:
        case value_t::boolean:
        case value_t::number_integer:
        case value_t::number_unsigned:
        case value_t::number_float:
        case value_t::binary:
