fn interpolate_to(
    &self,
    env: &HyperlinkEnvironment,
    values: &Values,
    dest: &mut Vec<u8>,
) {
    match *self {
        Part::Text(ref text) => dest.extend_from_slice(text),
        Part::Host => dest.extend_from_slice(
            env.host.as_ref().map(|s| s.as_bytes()).unwrap_or(b""),
        ),
        Part::WSLPrefix => dest.extend_from_slice(
            env.wsl_prefix.as_ref().map(|s| s.as_bytes()).unwrap_or(b""),
        ),
        Part::Path => dest.extend_from_slice(&values.path.0),
        Part::Line => {
            let line = DecimalFormatter::new(values.line.unwrap_or(1));
            dest.extend_from_slice(line.as_bytes());
        }
        Part::Column => {
            let column = DecimalFormatter::new(values.column.unwrap_or(1));
            dest.extend_from_slice(column.as_bytes());
        }
    }
}

fn render(msg: &'static str, lhs: &dyn Debug, rhs: &dyn Debug) -> Error {
    let mut lhs_buf = Buf::new();
    if fmt::write(&mut lhs_buf, format_args!("{:?}", lhs)).is_ok() {
        let mut rhs_buf = Buf::new();
        if fmt::write(&mut rhs_buf, format_args!("{:?}", rhs)).is_ok() {
            let lhs_str = lhs_buf.as_str();
            let rhs_str = rhs_buf.as_str();
            // "{msg} ({lhs} vs {rhs})"
            let len = msg.len() + 2 + lhs_str.len() + 4 + rhs_str.len() + 1;
            let mut string = String::with_capacity(len);
            string.push_str(msg);
            string.push_str(" (");
            string.push_str(lhs_str);
            string.push_str(" vs ");
            string.push_str(rhs_str);
            string.push(')');
            return Error::msg(string);
        }
    }
    Error::msg(msg)
}

