fn next_impl(&mut self, mut bytes: &[u8]) -> Option<(usize, usize)> {
    bytes = &bytes[..self.end];
    match bytes[self.pos..].find_byte(self.line_term) {
        None => {
            if self.pos < bytes.len() {
                let m = (self.pos, bytes.len());
                assert!(m.0 <= m.1);

                self.pos = m.1;
                Some(m)
            } else {
                None
            }
        }
        Some(line_end) => {
            let m = (self.pos, self.pos + line_end + 1);
            assert!(m.0 <= m.1);

            self.pos = m.1;
            Some(m)
        }
    }
}

