fn factor(
    qs1: Vec<GramQuery>,
    qs2: Vec<GramQuery>,
) -> (LiteralSet, LiteralSet, LiteralSet) {
    let (mut lits1, mut lits2) = (vec![], vec![]);
    for q in qs1 {
        lits1.push(q.unwrap_literal());
    }
    for q in qs2 {
        lits2.push(q.unwrap_literal());
    }

    let set1 = LiteralSet::from_vec(lits1);
    let set2 = LiteralSet::from_vec(lits2);
    set1.factor(set2)
}

