fn root_ignore(
    &mut self,
    errs: &mut PartialErrorBuilder,
) -> Option<Ignore> {
    let ignore = match self.ignore {
        RootIgnore::Unloaded(ref ignore) => ignore.clone(),
        RootIgnore::Loaded(ref ignore) => return Some(ignore.clone()),
        RootIgnore::NotDirectory | RootIgnore::Stdin => return None,
    };
    if !self.root.is_dir() {
        self.ignore = RootIgnore::NotDirectory;
        return None;
    }

    let (parents, err) = ignore.add_parents(&self.root);
    errs.maybe_push(err);
    let (root, err) = parents.add_child(&self.root);
    errs.maybe_push(err);
    self.ignore = RootIgnore::Loaded(root.clone());
    Some(root)
}

pub fn generate(&self, path: impl AsRef<Path>, path_separator: Option<&str>) -> OsString {
    use Token::*;
    let path = path.as_ref();

    match *self {
        Self::Tokens(ref tokens) => {
            let mut s = OsString::new();
            for token in tokens {
                match token {
                    Basename => s.push(Self::replace_separator(basename(path), path_separator)),
                    BasenameNoExt => s.push(Self::replace_separator(
                        &remove_extension(basename(path).as_ref()),
                        path_separator,
                    )),
                    NoExt => s.push(Self::replace_separator(
                        &remove_extension(path),
                        path_separator,
                    )),
                    Parent => s.push(Self::replace_separator(&dirname(path), path_separator)),
                    Placeholder => {
                        s.push(Self::replace_separator(path.as_ref(), path_separator))
                    }
                    Text(string) => s.push(string),
                }
            }
            s
        }
        Self::Text(ref text) => OsString::from(text),
    }
}

fn candidate_lines() {
    fn is_confirmed(m: LineMatchKind) -> bool {
        match m {
            LineMatchKind::Confirmed(_) => true,
            _ => false,
        }
    }
    fn is_candidate(m: LineMatchKind) -> bool {
        match m {
            LineMatchKind::Candidate(_) => true,
            _ => false,
        }
    }

    // With no line terminator set, we can't employ any optimizations,
    // so we get a confirmed match.
    let matcher = RegexMatcherBuilder::new().build(r"\wfoo\s").unwrap();
    let m = matcher.find_candidate_line(b"afoo ").unwrap().unwrap();
    assert!(is_confirmed(m));

    // With a line terminator and a regex specially crafted to have an
    // easy-to-detect inner literal, we can apply an optimization that
    // quickly finds candidate matches.
    let matcher = RegexMatcherBuilder::new()
        .line_terminator(Some(b'\n'))
        .build(r"\wfoo\s")
        .unwrap();
    let m = matcher.find_candidate_line(b"afoo ").unwrap().unwrap();
    assert!(is_candidate(m));
}

