fn send(&mut self, item: WorkerResult) -> Result<(), SendError<()>> {
    let mut batch = self.batch.lock();

    if self.needs_flush(batch.as_ref()) {
        drop(batch);
        self.batch = Batch::new();
        batch = self.batch.lock();
    }

    let items = batch.as_mut().unwrap();
    items.push(item);

    if items.len() == 1 {
        // New batch, send it over the channel
        self.tx
            .send(self.batch.clone())
            .map_err(|_| SendError(()))?;
    }

    Ok(())
}

fn record_matches(
    &mut self,
    searcher: &Searcher,
    bytes: &[u8],
    range: std::ops::Range<usize>,
) -> io::Result<()> {
    self.json.matches.clear();
    // If printing requires knowing the location of each individual match,
    // then compute and stored those right now for use later. While this
    // adds an extra copy for storing the matches, we do amortize the
    // allocation for it and this greatly simplifies the printing logic to
    // the extent that it's easy to ensure that we never do more than
    // one search to find the matches.
    let matches = &mut self.json.matches;
    find_iter_at_in_context(
        searcher,
        &self.matcher,
        bytes,
        range.clone(),
        |m| {
            let (s, e) = (m.start() - range.start, m.end() - range.start);
            matches.push(Match::new(s, e));
            true
        },
    )?;
    // Don't report empty matches appearing at the end of the bytes.
    if !matches.is_empty()
        && matches.last().unwrap().is_empty()
        && matches.last().unwrap().start() >= bytes.len()
    {
        matches.pop().unwrap();
    }
    Ok(())
}

