    true
}

fn fill(&mut self) -> Result<bool, S::Error> {
    assert!(self.rdr.buffer()[self.core.pos()..].is_empty());

    let already_binary = self.rdr.binary_byte_offset().is_some();
    let old_buf_len = self.rdr.buffer().len();
    let consumed = self.core.roll(self.rdr.buffer());
    self.rdr.consume(consumed);
    let didread = match self.rdr.fill() {
        Err(err) => return Err(S::Error::error_io(err)),
        Ok(didread) => didread,
    };
    if !already_binary {
        if let Some(offset) = self.rdr.binary_byte_offset() {
            if !self.core.binary_data(offset)? {
                return Ok(false);
            }
        }
    }
    if !didread || self.should_binary_quit() {
        return Ok(false);
    }
    // If rolling the buffer didn't result in consuming anything and if
    // re-filling the buffer didn't add any bytes, then the only thing in
    // our buffer is leftover context, which we no longer need since there
    // is nothing left to search. So forcefully quit.
    if consumed == 0 && old_buf_len == self.rdr.buffer().len() {
        self.rdr.consume(old_buf_len);
        return Ok(false);
    }
    Ok(true)
}

fn from(walk_err: Error) -> io::Error {
    let kind = match walk_err {
        Error { inner: ErrorInner::Io { ref err, .. }, .. } => err.kind(),
        Error { inner: ErrorInner::Loop { .. }, .. } => {
            io::ErrorKind::Other
        }
    };
    io::Error::new(kind, walk_err)
}

fn multiple_roots_keep_their_own_context() {
    let td = tmpdir();
    let root_a = td.path().join("a");
    let root_b = td.path().join("b");
    mkdirp(td.path().join(".git"));
    mkdirp(&root_a);
    mkdirp(&root_b);
    wfile(td.path().join(".gitignore"), "/a/*.tmp\n/b/*.log\n");

    let mut builder =
        builders([root_a.as_path(), Path::new("-"), root_b.as_path()]);
    builder.git_global(false);
    let mut ms = matchers(&builder);
    assert_eq!(ms.len(), 3);
    assert_eq!(ms[0].root(), root_a);
    assert_eq!(ms[1].root(), Path::new("-"));
    assert_eq!(ms[2].root(), root_b);
    assert!(matchedf(&mut ms[0], "drop.tmp").is_ignore());
    assert!(matchedf(&mut ms[0], "keep.log").is_none());
    assert!(matchedf(&mut ms[1], "anything").is_none());
    assert_eq!(ms[1].normalize("anything"), None);
    assert!(matchedf(&mut ms[2], "keep.tmp").is_none());
    assert!(matchedf(&mut ms[2], "drop.log").is_ignore());
}

fn replace(
    &mut self,
    searcher: &Searcher,
    bytes: &[u8],
    range: std::ops::Range<usize>,
) -> io::Result<()> {
    self.replacer.clear();
    if self.json.config.replacement.is_some() {
        let replacement =
            (*self.json.config.replacement).as_ref().map(|r| &*r).unwrap();
        self.replacer.replace_all(
            searcher,
            &self.matcher,
            bytes,
            range,
            replacement,
        )?;
    }
    Ok(())
}

