fn parse<F>(s: Option<&str>, f: F) -> Result<Self>
where
    F: Fn(&str) -> Result<T>,
{
    let (s, equality) = match s {
        Some("") | None => return Ok(Check::Ignore),
        Some(s) if s.starts_with('!') => (&s[1..], false),
        Some(s) => (s, true),
    };

    f(s).map(|x| {
        if equality {
            Check::Equal(x)
        } else {
            Check::NotEq(x)
        }
    })
}

