fn cross(&mut self, o: LiteralSet) {
    if o.is_empty() || o.has_only_empty() {
        return;
    }
    if self.is_empty() || self.has_only_empty() {
        *self = o;
        return;
    }

    let orig = mem::take(&mut self.lits);
    for selflit in &orig {
        for olit in &o.lits {
            let mut newlit = selflit.clone();
            newlit.push_str(olit);
            self.lits.push(newlit);
        }
    }
}

