unsafe fn construct<E>(
    error: E,
    vtable: &'static ErrorVTable,
    backtrace: Option<Backtrace>,
) -> Self
where
    E: StdError + Send + Sync + 'static,
{
    let inner: Box<ErrorImpl<E>> = Box::new(ErrorImpl {
        vtable,
        backtrace,
        _object: error,
    });
    // Erase the concrete type of E from the compile-time type system. This
    // is equivalent to the safe unsize coercion from Box<ErrorImpl<E>> to
    // Box<ErrorImpl<dyn StdError + Send + Sync + 'static>> except that the
    // result is a thin pointer. The necessary behavior for manipulating the
    // underlying ErrorImpl<E> is preserved in the vtable provided by the
    // caller rather than a builtin fat pointer vtable.
    let inner = Own::new(inner).cast::<ErrorImpl>();
    Error { inner }
}

fn walk_collect_parallel(
    prefix: &Path,
    builder: &WalkBuilder,
) -> Vec<String> {
    let mut paths = vec![];
    for dent in walk_collect_entries_parallel(builder) {
        let path = dent.path().strip_prefix(prefix).unwrap();
        if path.as_os_str().is_empty() {
            continue;
        }
        paths.push(normal_path(path.to_str().unwrap()));
    }
    paths.sort();
    paths
}

fn push(&mut self, path: &Path, separator: Option<&str>) -> io::Result<()> {
    if self.limit > 0 && self.count >= self.limit {
        self.finish()?;
    }

    let arg = self.path_arg.generate(path, separator);
    if !self
        .cmd
        .args_would_fit(iter::once(&arg).chain(&self.post_args))
    {
        self.finish()?;
    }

    self.cmd.try_arg(arg)?;
    self.count += 1;
    Ok(())
}

