}

fn depth_limits_apply_to_root() {
    let td = tmpdir();

    let mut b = builder(td.path());
    b.min_depth(Some(1));
    let mut m = one_matcher(&b);
    for path in ["", "."] {
        let root = matchedd(&mut m, path);
        assert!(root.is_none());
        assert!(!root.is_within_depth());
        assert!(root.should_descend());
    }

    let mut b = builder(td.path());
    b.max_depth(Some(0));
    let mut m = one_matcher(&b);
    for path in ["", "."] {
        let root = matchedd(&mut m, path);
        assert!(root.is_none());
        assert!(root.is_within_depth());
        assert!(!root.should_descend());
    }
}

