}

function hasModifierInLoop(condition, modifier) {
	if (condition.isInLoop(modifier)) {
		return true;
	}

	const funcNode = getEncloseFunctionDeclaration(modifier);

	if (!funcNode) {
		return false;
	}

	const funcVar = astUtils.getVariableByName(
		modifier.from.upper,
		funcNode.id.name,
	);

	return Boolean(funcVar && funcVar.references.some(condition.isInLoop));
}

function takeToken(cm, pos, precise, asArray) {
    var doc = cm.doc,
        mode = doc.mode,
        style
    pos = clipPos(doc, pos)
    var line = getLine(doc, pos.line),
        context = getContextBefore(cm, pos.line, precise)
    var stream = new StringStream(line.text, cm.options.tabSize, context),
        tokens
    if (asArray) {
        tokens = []
    }
    while ((asArray || stream.pos < pos.ch) && !stream.eol()) {
        stream.start = stream.pos
        style = readToken(mode, stream, context.state)
        if (asArray) {
            tokens.push(new Token(stream, style, copyState(doc.mode, context.state)))
        }
    }
    return asArray ? tokens : new Token(stream, style, context.state)
}

function notFound (reply) {
  if (reply[kRouteContext][kFourOhFourContext] === null) {
    reply.log.warn('Trying to send a NotFound error inside a 404 handler. Sending basic 404 response.')
    reply.code(404).send('404 Not Found')
    return
  }

  reply.request[kRouteContext] = reply[kRouteContext][kFourOhFourContext]

  // preHandler hook
  if (reply[kRouteContext].preHandler !== null) {
    preHandlerHookRunner(
      reply[kRouteContext].preHandler,
      reply.request,
      reply,
      internals.preHandlerCallback
    )
  } else {
    internals.preHandlerCallback(null, reply.request, reply)
  }
}

function checkReference(reference, index, references) {
	const identifier = reference.identifier;

	if (
		reference.init === false &&
		reference.isWrite() &&
		/*
		 * Destructuring assignments can have multiple default value,
		 * so possibly there are multiple writeable references for the same identifier.
		 */
		(index === 0 || references[index - 1].identifier !== identifier)
	) {
		context.report({
			node: identifier,
			messageId: "globalShouldNotBeModified",
			data: {
				name: identifier.name,
			},
		});
	}
}

function isKeySafeToQuote(node, options) {
  const key = getKey(node);
  if (key.type === "Identifier") {
    return true;
  }

  if (!isNumericLiteral(key)) {
    return false;
  }

  // Quoting number keys is safe in JS and Flow, but not in TypeScript (as
  // mentioned in `isKeySafeToUnquote`).
  if (isTypeScript(options)) {
    return false;
  }

  const printedNumber = printNumber(getRaw(key));

  return (
    // Avoid converting 999999999999999999999 to 1e+21, 0.99999999999999999 to 1 and 1.0 to 1.
    String(key.value) === printedNumber && isSimpleNumber(printedNumber)
  );
}

function compileSchemasForSerialization (context, compile) {
  if (!context.schema || !context.schema.response) {
    return
  }
  const { method, url } = context.config || {}
  context[responseSchema] = Object.keys(context.schema.response)
    .reduce(function (acc, statusCode) {
      const schema = context.schema.response[statusCode]
      statusCode = statusCode.toLowerCase()
      if (!scChecker.test(statusCode)) {
        throw new FST_ERR_SCH_RESPONSE_SCHEMA_NOT_NESTED_2XX()
      }

      if (schema.content) {
        const contentTypesSchemas = {}
        for (const mediaName of Object.keys(schema.content)) {
          const contentSchema = schema.content[mediaName].schema
          contentTypesSchemas[mediaName] = compile({
            schema: contentSchema,
            url,
            method,
            httpStatus: statusCode,
            contentType: mediaName
          })
        }
        acc[statusCode] = contentTypesSchemas
      } else {
        acc[statusCode] = compile({
          schema,
          url,
          method,
          httpStatus: statusCode
        })
      }

      return acc
    }, {})
}

