create(context) {
  return {
    [selector](callExpression) {
      const replacement = getReplacement(callExpression);
      if (!replacement) {
        return;
      }

      const getters = replacement.getters ?? [replacement.getter];
      const problem = {
        node: callExpression.callee,
        messageId,
        data: {
          replacement: new Intl.ListFormat("en-US", {
            type: "disjunction",
          }).format(getters.map((getter) => `\`AstPath#${getter}\``)),
          description: replacement.description,
        },
      };

      const useGetter = (getter) => (fixer) =>
        fixer.replaceTextRange(
          [callExpression.callee.property.range[0], callExpression.range[1]],
          getter,
        );

      if (replacement.getter) {
        problem.fix = useGetter(replacement.getter);
      } else {
        problem.suggest = getters.map((getter) => ({
          messageId: messageIdSuggestion,
          data: { getter },
          fix: useGetter(getter),
        }));
      }

      context.report(problem);
    },
  };
}

function guessEndOfLine(text) {
  const index = text.indexOf(CHARACTER_CR);
  if (index !== -1) {
    return text.charAt(index + 1) === CHARACTER_LF ? OPTION_CRLF : OPTION_CR;
  }
  return DEFAULT_OPTION;
}

function invertExpression(node) {
	if (
		node.type === "BinaryExpression" &&
		Object.hasOwn(OPERATOR_INVERSES, node.operator)
	) {
		const operatorToken = sourceCode.getFirstTokenBetween(
			node.left,
			node.right,
			token => token.value === node.operator,
		);
		const text = sourceCode.getText();

		return (
			text.slice(node.range[0], operatorToken.range[0]) +
			OPERATOR_INVERSES[node.operator] +
			text.slice(operatorToken.range[1], node.range[1])
		);
	}

	if (
		astUtils.getPrecedence(node) <
		astUtils.getPrecedence({ type: "UnaryExpression" })
	) {
		return `!(${astUtils.getParenthesisedText(sourceCode, node)})`;
	}
	return `!${astUtils.getParenthesisedText(sourceCode, node)}`;
}

function createError(message, options) {
