function fixIntoObjectDestructuring(fixer, node) {
	const rightNode = node.init;
	const sourceCode = context.sourceCode;

	// Don't fix if that would remove any comments. Only comments inside `rightNode.object` can be preserved.
	if (
		sourceCode.getCommentsInside(node).length >
		sourceCode.getCommentsInside(rightNode.object).length
	) {
		return null;
	}

	let objectText = sourceCode.getText(rightNode.object);

	if (
		astUtils.getPrecedence(rightNode.object) <
		PRECEDENCE_OF_ASSIGNMENT_EXPR
	) {
		objectText = `(${objectText})`;
	}

	return fixer.replaceText(
		node,
		`{${rightNode.property.name}} = ${objectText}`,
	);
}

function hasReferenceBeforeDeclaration(variable) {
	const declarationStart = variable.defs[0].node.range[0];

	return variable.references.some(reference => {
		const referenceStart = reference.identifier.range[0];

		/*
		 * Check if the reference occurs before the declaration.
		 * We don't need to check scopes because all references to this variable
		 * are already in variable.references (which only includes references
		 * that resolve to this specific variable binding).
		 */
		return !reference.init && referenceStart < declarationStart;
	});
}

function getVisitorKeys(node) {
  const type = node[typeProperty];

  /* c8 ignore next 5 */
  if (process.env.NODE_ENV !== "production" && type === undefined) {
    throw new Error(
      `Can't get node type, you must pass the wrong typeProperty '${typeProperty}'`,
    );
  }

  const keys = visitorKeys[type];
  /* c8 ignore next 5 */
  if (!Array.isArray(keys)) {
    throw Object.assign(new Error(`Missing visitor keys for '${type}'.`), {
      node,
    });
  }

  return keys;
}

