function isNextLineEmpty(node, text) {
  let newlineCount = 0;
  const textLength = text.length;
  for (let i = node.position.end.offset - 1; i < textLength; i++) {
    const char = text[i];

    if (char === "\n") {
      newlineCount++;
    }

    if (newlineCount === 1 && /\S/.test(char)) {
      return false;
    }

    if (newlineCount === 2) {
      return true;
    }
  }

  return false;
}

export function mapFactory(collection, mapper, context) {
  const mappedSequence = makeSequence(collection);
  mappedSequence.size = collection.size;
  mappedSequence.has = (key) => collection.has(key);
  mappedSequence.get = (key, notSetValue) => {
    const v = collection.get(key, NOT_SET);
    return v === NOT_SET
      ? notSetValue
      : mapper.call(context, v, key, collection);
  };
  mappedSequence.__iterateUncached = function (fn, reverse) {
    return collection.__iterate(
      (v, k, c) => fn(mapper.call(context, v, k, c), k, this) !== false,
      reverse
    );
  };
  mappedSequence.__iteratorUncached = function (type, reverse) {
    const iterator = collection.__iterator(ITERATE_ENTRIES, reverse);
    return new Iterator(() => {
      const step = iterator.next();
      if (step.done) {
        return step;
      }
      const entry = step.value;
      const key = entry[0];
      return iteratorValue(
        type,
        key,
        mapper.call(context, entry[1], key, collection),
        step
      );
    });
  };
  return mappedSequence;
}

map(fn) {
  /** @type{any} */
  let newNode;

  for (const NODES_KEY in NODES_KEYS) {
    const nodes = this[NODES_KEY];
    if (nodes) {
      const mappedNodes = mapNodesIfChanged(nodes, (node) => node.map(fn));
      if (newNode !== nodes) {
        newNode ??= new Node({ parent: this.parent });
        newNode.setProperty(NODES_KEY, mappedNodes);
      }
    }
  }

  if (newNode) {
    for (const key in this) {
      if (!(key in NODES_KEYS)) {
        newNode[key] = this[key];
      }
    }
  }

  return fn(newNode || this);
}

