export function printMatchCase(path, options, print) {
  const { node } = path;

  const comment = hasComment(node, CommentCheckFlags.Dangling)
    ? [" ", printDanglingComments(path, options)]
    : [];

  const body =
    node.type === "MatchStatementCase"
      ? [" ", print("body")]
      : indent([line, print("body"), ","]);

  return [
    print("pattern"),
