function onData (chunk) {
  // A custom preParsing stream may still emit strings
  if (typeof chunk === 'string') {
    chunk = Buffer.from(chunk)
  }
  receivedLength += chunk.length
  const { receivedEncodedLength = 0 } = payload
  // The resulting body length must not exceed bodyLimit (see "zip bomb").
  // The case when encoded length is larger than received length is rather theoretical,
  // unless the stream returned by preParsing hook is broken and reports wrong value.
  if (receivedLength > limit || receivedEncodedLength > limit) {
    payload.removeListener('data', onData)
    payload.removeListener('end', onEnd)
    payload.removeListener('error', onEnd)
    done(new FST_ERR_CTP_BODY_TOO_LARGE(), undefined)
    return
  }

  chunks.push(chunk)
}

async function run() {
  const api = start('api', process.execPath, ['./server/index.mjs'])
  const web = start('web', viteCommand, [], {
    VITE_PAGINATION_API_PORT: String(API_PORT),
  })

  const shutdown = async () => {
    await Promise.all([stop(web), stop(api)])
  }

  process.on('SIGINT', shutdown)
  process.on('SIGTERM', shutdown)

  const [winner] = await Promise.race([
    once(api, 'exit').then(([code]) => ({ name: 'api', code })),
    once(web, 'exit').then(([code]) => ({ name: 'web', code })),
  ])

  await shutdown()

  if (winner.code !== 0 && winner.code !== null) {
    process.exitCode = winner.code
  } else {
    process.exitCode = 1
  }
}

