IfStatement(node) {
	const test = node.test,
		conditionsToCheck =
			test.type === "LogicalExpression" &&
			test.operator === "&&"
				? [test, ...splitByAnd(test)]
				: [test];
	let current = node,
		listToCheck = conditionsToCheck.map(c =>
			splitByOr(c).map(splitByAnd),
		);

	while (
