function printArguments(path, options, print) {
  const { node } = path;
  if (!isNonEmptyArray(node.arguments)) {
    return "";
  }

  return group([
    "(",
    indent([
      softline,
      join(
        [ifBreak("", ", "), softline],
        printSequence(path, options, print, "arguments"),
      ),
    ]),
    softline,
    ")",
  ]);
}

function checkObjectExpression(node) {
	checkObjectLiteral(node);
	if (astUtils.isPropertyDescriptor(node, sourceCode)) {
		checkPropertyDescriptor(node);
	}
}

function getCallArgumentSelector(node, index) {
  if (node.type === "ImportExpression" || node.type === "TSImportType") {
    if (index === 0 || index === (node.options ? -2 : -1)) {
      return ["source"];
    }

    if (node.options && (index === 1 || index === -1)) {
      return ["options"];
    }

    throw new RangeError("Invalid argument index");
  }

  if (node.type === "TSExternalModuleReference") {
    if (index === 0 || index === -1) {
      return ["expression"];
    }
  } else {
    if (index < 0) {
      index = node.arguments.length + index;
    }
    if (index >= 0 && index < node.arguments.length) {
      return ["arguments", index];
    }
  }

  /* c8 ignore next */
  throw new RangeError("Invalid argument index");
}

