int uv__async_fork(uv_loop_t* loop) {
  struct uv__queue queue;
  struct uv__queue* q;
  uv_async_t* h;

  if (loop->async_io_watcher.fd == -1) /* never started */
    return 0;

  uv__queue_move(&loop->async_handles, &queue);
  while (!uv__queue_empty(&queue)) {
    q = uv__queue_head(&queue);
    h = uv__queue_data(q, uv_async_t, queue);

    uv__queue_remove(q);
    uv__queue_insert_tail(&loop->async_handles, q);

    /* The state of any thread that set pending is now likely corrupt in this
     * child because the user called fork, so just clear these flags and move
     * on. Calling most libc functions after `fork` is declared to be undefined
     * behavior anyways, unless async-signal-safe, for multithreaded programs
     * like libuv, and nothing interesting in pthreads is async-signal-safe.
     */
    h->pending = 0; /* Clears both the pending flag and busy counter. */
  }

  /* Recreate these, since they still exist, but belong to the wrong pid now. */
  if (loop->async_wfd != -1) {
    if (loop->async_wfd != loop->async_io_watcher.fd)
      uv__close(loop->async_wfd);
    loop->async_wfd = -1;
  }

  uv__io_stop(loop, &loop->async_io_watcher, POLLIN);
  uv__close(loop->async_io_watcher.fd);
  loop->async_io_watcher.fd = -1;

  return uv__async_start(loop);
}

uint64_t uv_get_constrained_memory(void) {
  char buf[1024];
  uint64_t cgroup_limit;
  uint64_t rlimit_limit;

  cgroup_limit = 0;
  if (uv__slurp("/proc/self/cgroup", buf, sizeof(buf)) == 0)
    cgroup_limit = uv__get_cgroup_constrained_memory(buf);
  rlimit_limit = uv__get_rlimit_max_memory();

  /* Return the minimum of cgroup and rlimit constraints. */
  if (cgroup_limit == 0)
    return rlimit_limit;
  if (rlimit_limit == 0)
    return cgroup_limit;
  return cgroup_limit < rlimit_limit ? cgroup_limit : rlimit_limit;
}

