func keyFieldLines(h *fasthttp.RequestHeader, name string, normalized bool) [][]byte {
	switch {
	case utils.EqualFold(name, fiber.HeaderCookie):
		h.Cookie("") // collectCookies; the lookup itself is expected to miss

	case utils.EqualFold(name, fiber.HeaderContentType) && mediatype.IsForm(h.ContentType()):
		// Fold here rather than read whatever arrived: the key is built once before
		// the handler and once after, and the form accessors lowercase this header
		// in between, so the entry landed under a key no lookup would produce.
		mediatype.NormalizeRequestContentType(h)
	}

	return fieldname.Lines(h, name, normalized)
}

func extractFieldFromError(err error) string {
	var convErr schema.ConversionError
	if errors.As(err, &convErr) {
		return convErr.Key
	}
	var unknownKey schema.UnknownKeyError
	if errors.As(err, &unknownKey) {
		return unknownKey.Key
	}
	var emptyField schema.EmptyFieldError
	if errors.As(err, &emptyField) {
		return emptyField.Key
	}
	var multiErr schema.MultiError
	if errors.As(err, &multiErr) {
		for k := range multiErr {
			return k
		}
	}
	var unmarshalErr *json.UnmarshalTypeError
	if errors.As(err, &unmarshalErr) {
		return unmarshalErr.Field
	}
	return ""
}

func equalFieldType(out any, kind reflect.Kind, key, aliasTag string) bool {
	if out == nil {
		return false
	}

	// The type answers everything here; a reflect.Value is only taken to tell
	// a nil map from one the decoder can fill.
	typ := reflect.TypeOf(out)
	typKind := typ.Kind()
	isPointer := typKind == reflect.Pointer
	for typKind == reflect.Pointer {
		typ = typ.Elem()
		typKind = typ.Kind()
	}

	switch typKind {
	case reflect.Map:
		// Only a slice-valued map can hold more than one value per key. A nil
		// map counts when a pointer to it was passed, since the decoder
		// allocates it before filling it; a nil one by value stays unfillable.
		if !isPointer && reflect.ValueOf(out).IsNil() {
			return false
		}
		return typ.Key().Kind() == reflect.String &&
			typ.Elem().Kind() == reflect.Slice && kind == reflect.Slice
	case reflect.Struct:
		// A struct is decoded through a pointer; a plain value cannot be set.
		if !isPointer {
			return false
		}
	default:
		return false
	}

	// Lower the key only once a struct lookup is needed.
	return structKeyKind(getFieldCache(aliasTag), typ, kind, utilsstrings.ToLower(key), aliasTag)
}

