func New(config ...Config) fiber.Handler {
	cfg := configDefault(config...)

	// Initialize
	rules := orderedRules(cfg)
	compiled := make([]compiledRule, 0, len(rules))
	for _, rule := range rules {
		compiled = append(compiled, compiledRule{
			pattern: compilePattern(rule.From),
			to:      rule.To,
		})
	}

	// Bound before the closure so it captures this alone.
	next := cfg.Next

	// Middleware function
	return func(c fiber.Ctx) error {
		// Next request to skip middleware
		if next != nil && next(c) {
			return c.Next()
		}
		// Rewrite
		for _, rule := range compiled {
			replacer := captureTokens(rule.pattern, c.Path())
			if replacer != nil {
				c.Path(replacer.Replace(rule.to))
				break
			}
		}
		return c.Next()
	}
}

func (Encoder) AppendInts8(dst []byte, vals []int8) []byte {
	if len(vals) == 0 {
		return append(dst, '[', ']')
	}
	dst = append(dst, '[')
	dst = strconv.AppendInt(dst, int64(vals[0]), 10)
	if len(vals) > 1 {
		for _, val := range vals[1:] {
			dst = strconv.AppendInt(append(dst, ','), int64(val), 10)
		}
	}
	dst = append(dst, ']')
	return dst
}

func isIPLiteral(host string) bool {
	if len(host) >= 2 && host[0] == '[' && host[len(host)-1] == ']' {
		host = host[1 : len(host)-1]
	}

	// Equivalent to net.ParseIP(host) != nil: utils.ParseIPv4/ParseIPv6
	// accept the same strings once zoned addresses (which net.ParseIP
	// rejects) are screened out, without allocating on either outcome.
	if strings.IndexByte(host, '%') >= 0 {
		return false
	}
	if _, ok := utils.ParseIPv4(host); ok {
		return true
	}
	_, ok := utils.ParseIPv6(host)
	return ok
}

