func unescapeHeaderValue(v []byte) ([]byte, error) {
	if bytes.IndexByte(v, '\\') == -1 {
		return v, nil
	}
	res := make([]byte, 0, len(v))
	escaping := false
	for i, c := range v {
		if escaping {
			res = append(res, c)
			escaping = false
			continue
		}
		if c == '\\' {
			// invalid escape at end of string
			if i == len(v)-1 {
				return nil, errInvalidEscapeSequence
			}
			escaping = true
			continue
		}
		res = append(res, c)
	}
	if escaping {
		return nil, errInvalidEscapeSequence
	}
	return res, nil
}

func appendIntPadded(buf *bytebufferpool.ByteBuffer, v, width int) {
	var scratch [maxIntLen]byte
	s := utils.AppendInt(scratch[:0], int64(v))
	for i := len(s); i < width; i++ {
		buf.WriteByte(' ')
	}
	buf.Write(s)
}

