func buildErrorChainString(err error, withType bool) string {
	if err == nil {
		return ""
	}

	var chain string
	errs := unwrapAll(err)
	for i := range errs {
		if i != 0 {
			chain += "\n\t"
		}
		chain += fmt.Sprintf("%q", errs[i].Error())
		if withType {
			chain += fmt.Sprintf(" (%T)", errs[i])
		}
	}
	return chain
}

