private attachSseAbortSignal<TRequest>(req: TRequest): void {
  const carrier = req as TRequest & {
    raw?: unknown;
    [SSE_ABORT_CONTROLLER]?: AbortController;
  };
  // Attach to both the framework request and its raw form (when present), since
  // @SseSignal() reads from the execution-context request while
  // RouterResponseController.sse() operates on the raw request.
  if (!carrier[SSE_ABORT_CONTROLLER]) {
    carrier[SSE_ABORT_CONTROLLER] = new AbortController();
  }
  if (carrier.raw && !(carrier.raw as object)[SSE_ABORT_CONTROLLER]) {
    (carrier.raw as object)[SSE_ABORT_CONTROLLER] =
      carrier[SSE_ABORT_CONTROLLER];
  }
}

function pull() {
  if (state !== 'idle') {
    return;
  }
  state = 'pending';

  const next = iterator.next();
  next
    .then((result) => {
      if (result.done) {
        state = 'done';
        onResult({ status: 'return', value: result.value });
        cleanup();
        return;
      }
      state = 'idle';
      onResult({ status: 'yield', value: result.value });
    })
    .catch((cause) => {
      onResult({ status: 'error', error: cause });
      cleanup();
    });
}

private getColumnsToProcess(aliasName: string, metadata: EntityMetadata) {
    let metadatas = this.columnsCache.get(aliasName)
    if (!metadatas) {
        metadatas = new Map()
        this.columnsCache.set(aliasName, metadatas)
    }
    let columns = metadatas.get(metadata)
    if (!columns) {
        columns = metadata.columns
            .filter(
                (column) =>
                    !column.isVirtual &&
                    // if user does not selected the whole entity or he used partial selection and does not select this particular column
                    // then we don't add this column and its value into the entity
                    (this.selections.has(aliasName) ||
                        this.selections.has(
                            `${aliasName}.${column.propertyPath}`,
                        )) &&
                    // if table inheritance is used make sure this column is not child's column
                    !metadata.childEntityMetadatas.some(
                        (childMetadata) =>
                            childMetadata.target === column.target,
                    ),
            )
            .map((column) => [
                this.buildAlias(aliasName, column.databaseName),
                column,
            ])
        metadatas.set(metadata, columns)
    }
    return columns
}

function getGenericTypeNamesFromText(text: string): string[] {
  // Extract generic type names from the declaration brackets
  const bracketMatch = text.match(/\[([^\]]+)\]/);
  if (!bracketMatch) return [];
  const content = bracketMatch[1];

  // Split by commas and extract type names (before constraints like "any", "~[]T", etc.)
  const names = content
    .split(',')
    .map(s => s.trim())
    .map(s => (s.match(/^([A-Z][A-Za-z0-9_]*)\b/) || [])[1])
    .filter(Boolean) as string[];

  // Also look for any other capitalized identifiers that might be generic types
  // This catches cases where generics are used as types throughout the signature
  const allCapsIdentifiers = text.match(/\b([A-Z][A-Za-z0-9_]*)\b/g) || [];
  const additionalNames = allCapsIdentifiers.filter(name => 
    !['func', 'any', 'bool', 'int', 'string', 'float', 'byte', 'rune'].includes(name) &&
    !name.match(/^[A-Z][a-z]+$/) // Exclude function names
  );

  return Array.from(new Set([...names, ...additionalNames]));
}

function validateRunnerChunk(
  this: PluginContext,
  chunk: RenderedChunk,
  importBindings: ImportBindings[],
) {
  for (const { id, bindings } of importBindings) {
    if (
      !id.startsWith('./') &&
      !id.startsWith('../') &&
      !id.startsWith('#') &&
      // index and moduleRunner have a common chunk
      !id.startsWith('chunks/') &&
      !id.startsWith('types.d')
    ) {
      this.warn(
        `${chunk.fileName} imports "${bindings.join(', ')}" from "${id}" which is not allowed`,
      )
      process.exitCode = 1
    }
  }
}

