public handleClose() {
  if (this.routingMap.size > 0) {
    const err = new Error('Connection closed');
    const callbacks = [...this.routingMap.values()];
    this.routingMap.clear();

    for (const callback of callbacks) {
      try {
        callback({ err });
      } catch (callbackErr) {
        // A failing callback must not keep the remaining requests pending
        // nor prevent the connection from being closed.
        this.logger.error(callbackErr);
      }
    }
  }
  // The listeners expect a message to parse, so they cannot carry the error.
  this.responseEmitter?.removeAllListeners();
}

export function mapCompatDirectiveHook(
  name: keyof ObjectDirective,
  dir: ObjectDirective & LegacyDirective,
  instance: ComponentInternalInstance | null,
): DirectiveHook | DirectiveHook[] | undefined {
  const mappedName = legacyDirectiveHookMap[name]
  if (mappedName) {
    if (isArray(mappedName)) {
      const hook: DirectiveHook[] = []
      mappedName.forEach(mapped => {
        const mappedHook = dir[mapped]
        if (mappedHook) {
          softAssertCompatEnabled(
            DeprecationTypes.CUSTOM_DIR,
            instance,
            mapped,
            name,
          )
          hook.push(mappedHook)
        }
      })
      return hook.length ? hook : undefined
    } else {
      if (dir[mappedName]) {
        softAssertCompatEnabled(
          DeprecationTypes.CUSTOM_DIR,
          instance,
          mappedName,
          name,
        )
      }
      return dir[mappedName]
    }
  }
}

function joinUrlSegments(a: string, b: string): string {
  if (!a || !b) {
    return a || b || ''
