export function drainRequest(raw: IncomingMessage): Promise<void> {
  raw.unpipe();
  if (raw.readableEnded || raw.destroyed) {
    return Promise.resolve();
  }
  return new Promise(resolve => {
    const done = () => resolve();
    raw.once('end', done);
    raw.once('close', done);
    raw.once('error', done);
    raw.resume();
  });
}

function isClientLockable(
  client: Socket,
  transportName: string,
  lockType: "read" | "write",
) {
  switch (transportName) {
    case "polling":
      return (
        client.transport.name === "polling" &&
        (lockType === "write" || !client.transport.writable)
      );
    case "websocket":
    case "webtransport":
      return (
        client.transport.name === "polling" &&
        !client.upgrading &&
        !client.upgraded
      );
  }
}

