function convertTypeToSchema(
  type: ts.Type,
  ctx: SchemaCtx,
  depth: number,
): SchemaObject {
  if (ctx.visited.has(type)) {
    return handleCyclicRef(type, ctx);
  }

  const flags = type.getFlags();

  const primitive = convertPrimitiveOrLiteral(type, flags, ctx.checker);
  if (primitive) {
    return primitive;
  }

  if (type.isUnion()) {
    ctx.visited.add(type);
    const result = convertUnionType(type, ctx, depth);
    ctx.visited.delete(type);
    return result;
  }
  if (type.isIntersection()) {
    ctx.visited.add(type);
    const result = convertIntersectionType(type, ctx, depth);
    ctx.visited.delete(type);
    return result;
  }
  if (isFunctionType(type)) {
    return {};
  }
  if (isObjectType(type)) {
    return convertObjectType(type, ctx, depth);
  }

  return {};
}

function resolveIndexType(
  ctx: TypeResolveContext,
  node: TSIndexedAccessType,
  scope: TypeScope,
): (TSType & MaybeWithScope)[] {
  if (node.indexType.type === 'TSNumberKeyword') {
    return resolveArrayElementType(ctx, node.objectType, scope)
  }

  const { indexType, objectType } = node
  const types: TSType[] = []
  let keys: string[]
  let resolved: ResolvedElements
  if (indexType.type === 'TSStringKeyword') {
    resolved = resolveTypeElements(ctx, objectType, scope)
    keys = Object.keys(resolved.props)
  } else {
    keys = resolveStringType(ctx, indexType, scope)
    resolved = resolveTypeElements(ctx, objectType, scope)
  }
  for (const key of keys) {
    const targetType = resolved.props[key]?.typeAnnotation?.typeAnnotation
    if (targetType) {
      ;(targetType as TSType & MaybeWithScope)._ownerScope =
        resolved.props[key]._ownerScope
      types.push(targetType)
    }
  }
  return types
}

