_parse(input: ParseInput): ParseReturnType<this["_output"]> {
  const parsedType = this._getType(input);
  if (parsedType !== ZodParsedType.null) {
    const ctx = this._getOrReturnCtx(input);
    addIssueToContext(ctx, {
      code: ZodIssueCode.invalid_type,
      expected: ZodParsedType.null,
      received: ctx.parsedType,
    });
    return INVALID;
  }
  return OK(input.data);
}

function validateFallback(
  schema: schemas.$ZodType,
  value: unknown,
  _ctx?: schemas.ParseContext<errors.$ZodIssue>
): boolean {
  const ctx: schemas.ParseContextInternal = _ctx
    ? { ..._ctx, async: false, abortEarly: true }
    : { async: false, abortEarly: true };
  const fallbackRun = (schema._zod.bag as CompiledBag).fallbackRun;
  let result: unknown;
  if (fallbackRun) {
    // skip nested fast paths on the fallback, so user callbacks keep the at-most-twice bound
    (ctx as Record<symbol, unknown>)[COMPILE_FALLBACK] = true;
    result = fallbackRun({ value, issues: [] }, ctx);
  } else {
    result = schema._zod.run({ value, issues: [] }, ctx);
  }
  if (result instanceof Promise) {
    throw new core.$ZodAsyncError();
  }
  return (result as schemas.ParsePayload).issues.length === 0;
}

getModulesByFile(file: string): Set<ModuleNode> | undefined {
  // Until Vite 5.1.x, the moduleGraph contained modules from both the browser and server
  // We maintain backwards compatibility by returning a Set of module proxies assuming
  // that the modules for a certain file are the same in both the browser and server
  const clientModules = this._client.getModulesByFile(file)
  const ssrModules = this._ssr.getModulesByFile(file)
  if (!clientModules && !ssrModules) {
    return undefined
  }
  const result = new Set<ModuleNode>()
  if (clientModules) {
    for (const mod of clientModules) {
      result.add(this.getBackwardCompatibleBrowserModuleNode(mod)!)
    }
  }
  if (ssrModules) {
    for (const mod of ssrModules) {
      if (mod.id == null || !this._client.getModuleById(mod.id)) {
        result.add(this.getBackwardCompatibleServerModuleNode(mod)!)
      }
    }
  }
  return result
}

public addScopedEnhancersMetadata() {
  iterate(this.applicationProvidersApplyMap)
    .filter(wrapper => this.isRequestOrTransient(wrapper.scope!))
    .forEach(({ moduleKey, providerKey }) => {
      const modulesContainer = this.container.getModules();
      const { injectables } = modulesContainer.get(moduleKey)!;
      const instanceWrapper = injectables.get(providerKey);

      const iterableIterator = modulesContainer.values();
      iterate(iterableIterator)
        .map(moduleRef =>
          Array.from<InstanceWrapper>(moduleRef.controllers.values()).concat(
            moduleRef.entryProviders,
          ),
        )
        .flatten()
        .forEach(controllerOrEntryProvider =>
          controllerOrEntryProvider.addEnhancerMetadata(instanceWrapper!),
        );
    });
}

