function reactionRunner() {
    isScheduled = false
    if (r.isDisposed) {
        return
    }
    let changed: boolean = false
    const oldValue = value
    r.track(() => {
        const nextValue = allowStateChanges(false, () => expression(r))
        changed = firstTime || !equals(value, nextValue)
        value = nextValue
    })

    // This casting is nesessary as TS cannot infer proper type in current function implementation
    type OldValue = FireImmediately extends true ? T | undefined : T
    if (firstTime && opts.fireImmediately!) {
        effectAction(value, oldValue as OldValue, r)
    } else if (!firstTime && changed) {
        effectAction(value, oldValue as OldValue, r)
    }
    firstTime = false
}

function storeFile(
  storage: MultipartStorageEngine,
  req: FastifyRequest,
  file: IncomingMultipartFile,
) {
  return new Promise<Partial<UploadedMultipartFile> | typeof ABORTED>(
    (resolve, reject) => {
      const stream = file.stream;
      if (stream.destroyed) {
        return resolve(ABORTED);
      }
      let aborted = false;
      const onClose = () => {
        if (!stream.readableEnded && !stream.errored) {
          aborted = true;
          resolve(ABORTED);
        }
      };
      stream.once('close', onClose);
      storage._handleFile(req, file, (err, info) => {
        stream.off('close', onClose);
        if (!aborted) {
          return err ? reject(err) : resolve(info ?? {});
        }
        const stored = Object.assign(
          file,
          err ? {} : info,
        ) as unknown as UploadedMultipartFile;
        if (!err || stored.path) {
          removeFiles(storage, req, [stored]).catch(() => undefined);
        }
      });
    },
  );
}

