async updateDDL(query: string, parameters?: any[]): Promise<void> {
    if (this.isReleased) throw new QueryRunnerAlreadyReleasedError()

    this.driver.dataSource.logger.logQuery(query, parameters, this)
    try {
        const queryStartTime = Date.now()
        const [operation] =
            await this.driver.instanceDatabase.updateSchema(query)
        await operation.promise()
        // log slow queries if maxQueryExecution time is set
        const maxQueryExecutionTime =
            this.driver.options.maxQueryExecutionTime
        const queryEndTime = Date.now()
        const queryExecutionTime = queryEndTime - queryStartTime
        if (
            maxQueryExecutionTime &&
            queryExecutionTime > maxQueryExecutionTime
        )
            this.driver.dataSource.logger.logQuerySlow(
                queryExecutionTime,
                query,
                parameters,
                this,
            )
    } catch (err) {
        this.driver.dataSource.logger.logQueryError(
            err,
            query,
            parameters,
            this,
        )
        throw new QueryFailedError(query, parameters, err)
    }
}

export function createPluginHookUtils(
  plugins: readonly Plugin[],
): PluginHookUtils {
  // sort plugins per hook
  const sortedPluginsCache = new Map<keyof Plugin, Plugin[]>()
  function getSortedPlugins<K extends keyof Plugin>(
    hookName: K,
  ): PluginWithRequiredHook<K>[] {
    if (sortedPluginsCache.has(hookName))
      return sortedPluginsCache.get(hookName) as PluginWithRequiredHook<K>[]
    const sorted = getSortedPluginsByHook(hookName, plugins)
    sortedPluginsCache.set(hookName, sorted)
    return sorted
  }
  function getSortedPluginHooks<K extends keyof Plugin>(
    hookName: K,
  ): NonNullable<HookHandler<Plugin[K]>>[] {
    const plugins = getSortedPlugins(hookName)
    return plugins.map((p) => getHookHandler(p[hookName])).filter(Boolean)
  }

  return {
    getSortedPlugins,
    getSortedPluginHooks,
  }
}

get<S extends Schema>(schema: S): $replace<Meta, S> | undefined {
  // return this._map.get(schema) as any;

  // inherit metadata
  const p = schema._zod.parent as Schema;
  if (p) {
    const pm: any = { ...(this.get(p) ?? {}) };
    delete pm.id; // do not inherit id
    const f = { ...pm, ...this._map.get(schema) } as any;
    return Object.keys(f).length ? f : undefined;
  }
  return this._map.get(schema) as any;
}

