function printBasicValue(value: unknown): string | undefined {
  if (value == null) {
    return String(value)
  }
  if (typeof value === 'string') {
    return JSON.stringify(value)
  }
  if (typeof value === 'number') {
    return Object.is(value, -0) ? '-0' : String(value)
  }
  if (typeof value === 'bigint') {
    return `${value}n`
  }
  if (typeof value === 'boolean' || typeof value === 'symbol') {
    return String(value)
  }
  if (typeof value === 'function') {
    return value.name ? `[Function: ${value.name}]` : '[Function]'
  }

  const type = objectToString.call(value)
  if (type === '[object Date]') {
    return Number.isNaN(+(value as Date))
      ? 'Date { NaN }'
      : (value as Date).toISOString()
  }
  if (type === '[object Error]' || value instanceof Error) {
    return `[${errorToString.call(value)}]`
  }
}

function setActiveBranch(suspense: SuspenseBoundary, branch: VNode) {
  suspense.activeBranch = branch
  const { vnode, parentComponent } = suspense
  let el = branch.el
  // if branch has no el after patch, it's a HOC wrapping async components
  // drill and locate the placeholder comment node
  while (!el && branch.component) {
    branch = branch.component.subTree
    el = branch.el
  }
  vnode.el = el
  // in case suspense is the root node of a component,
  // recursively update the HOC el
  if (parentComponent && parentComponent.subTree === vnode) {
    parentComponent.vnode.el = el
    updateHOCHostEl(parentComponent, el)
  }
}

export async function until(
  check: () => boolean | Promise<boolean>,
  timeout = 5_000,
) {
  const start = Date.now();
  while (!(await check())) {
    if (Date.now() - start > timeout) throw new Error('Timed out waiting');
    await sleep(10);
  }
}

