function optimizeSafeRealPathSync() {
  // Check the availability `fs.realpathSync.native`
  // in Windows virtual and RAM disks that bypass the Volume Mount Manager, in programs such as imDisk
  // get the error EISDIR: illegal operation on a directory
  try {
    fs.realpathSync.native(path.resolve('./'))
  } catch (error) {
    if (error.message.includes('EISDIR: illegal operation on a directory')) {
      safeRealpathSync = fs.realpathSync
      return
    }
  }
  exec('net use', { windowsHide: true }, (error, stdout) => {
    if (error) return
    const lines = stdout.split('\n')
    // OK           Y:        \\NETWORKA\Foo         Microsoft Windows Network
    // OK           Z:        \\NETWORKA\Bar         Microsoft Windows Network
    for (const line of lines) {
      const m = parseNetUseRE.exec(line)
      if (m) windowsNetworkMap.set(m[2], m[1])
    }
    if (windowsNetworkMap.size === 0) {
      safeRealpathSync = fs.realpathSync.native
    } else {
      safeRealpathSync = windowsMappedRealpathSync
    }
  })
}

export const transformFilter: NodeTransform = (node, context) => {
  if (!isCompatEnabled(CompilerDeprecationTypes.COMPILER_FILTERS, context)) {
    return
  }

  if (node.type === NodeTypes.INTERPOLATION) {
    // filter rewrite is applied before expression transform so only
    // simple expressions are possible at this stage
    rewriteFilter(node.content, context)
  } else if (node.type === NodeTypes.ELEMENT) {
    node.props.forEach((prop: AttributeNode | DirectiveNode) => {
      if (
        prop.type === NodeTypes.DIRECTIVE &&
        prop.name !== 'for' &&
        prop.exp
      ) {
        rewriteFilter(prop.exp, context)
      }
    })
  }
}

function generateRegexConstantsForType(
  typeName: string,
  schema: OpenAPIV3.SchemaObject | OpenAPIV3.ReferenceObject,
  ctx: OazapftsContext
): ts.VariableStatement[] {
  const resolvedSchema = resolve(schema, ctx);
  if (!resolvedSchema || !('properties' in resolvedSchema) || !resolvedSchema.properties) return [];

  const constants: ts.VariableStatement[] = [];

  for (const [propertyName, property] of Object.entries(resolvedSchema.properties)) {
    const pattern = getPatternFromProperty(property, ctx);
    if (!pattern) continue;

    const constantName = camelCase(`${typeName} ${propertyName} Pattern`);
    const escapedPattern = pattern.replaceAll('/', String.raw`\/`);
    const regexLiteral = factory.createRegularExpressionLiteral(`/${escapedPattern}/`);

    constants.push(
      factory.createVariableStatement(
        [factory.createModifier(ts.SyntaxKind.ExportKeyword)],
        factory.createVariableDeclarationList(
          [
            factory.createVariableDeclaration(
              factory.createIdentifier(constantName),
              undefined,
              undefined,
              regexLiteral
            ),
          ],
          ts.NodeFlags.Const
        )
      )
    );
  }

  return constants;
}

