function mergeInput(a?: InputOption, b?: InputOption): InputOption | undefined {
  if (!a) return b
  if (!b) return a

  if (typeof a === 'string' && typeof b === 'string') {
    return [a, b]
  }
  if (Array.isArray(a) && (typeof b === 'string' || Array.isArray(b))) {
    return [...a, ...(Array.isArray(b) ? b : [b])]
  }
  if (Array.isArray(b) && (typeof a === 'string' || Array.isArray(a))) {
    return [...(Array.isArray(a) ? a : [a]), ...b]
  }
  if (typeof a !== 'string' && !Array.isArray(a)) {
    return {
      ...a,
      ...normalizeToInputObject(b),
    }
  }
  // b is a record
  return {
    ...normalizeToInputObject(a),
    ...(b as Record<string, string>),
  }
}

const fn: $Parse = (schema, value, _ctx, _params) => {
  const ctx: schemas.ParseContextInternal = _ctx ? { ..._ctx, async: false } : { async: false };
  const result = schema._zod.run({ value, issues: [] }, ctx);
  if (result instanceof Promise) {
    throw new core.$ZodAsyncError();
  }
  if (result.issues.length) {
    const e = new (_params?.Err ?? _Err)(result.issues.map((iss) => util.finalizeIssue(iss, ctx, core.config())));
    util.captureStackTrace(e, _params?.callee ?? fn);
    throw e;
  }
  return result.value as core.output<typeof schema>;
};

renderChunk(code, chunk, outputOptions) {
  if (!code.includes(prefix)) return

  return code.replace(
    /__vite_buildTimeImportMetaUrl_(\d+)/g,
    (_, index) => {
      const originalFile = Object.keys(idMap).find(
        (key) => idMap[key] === +index,
      )
      if (!originalFile) {
        throw new Error(
          `Could not find original file for ${prefix}${index} in ${chunk.fileName}`,
        )
      }
      const outputFile = path.resolve(outputOptions.dir!, chunk.fileName)
      const relativePath = path
        .relative(path.dirname(outputFile), originalFile)
        .replaceAll('\\', '/')

      if (outputOptions.format === 'es') {
        return `new URL(${JSON.stringify(relativePath)}, import.meta.url)`
      } else if (outputOptions.format === 'cjs') {
        return `new URL(${JSON.stringify(
          relativePath,
        )}, require('node:url').pathToFileURL(__filename))`
      } else {
        throw new Error(`Unsupported output format ${outputOptions.format}`)
      }
    },
  )
}

protected createIndexSql(table: Table, index: TableIndex): Query {
