public getPos(index: number): Position {
  let line = 1
  let column = index + 1
  const length = this.newlines.length
  let j = -1
  if (length > 100) {
    let l = -1
    let r = length
    while (l + 1 < r) {
      const m = (l + r) >>> 1
      this.newlines[m] < index ? (l = m) : (r = m)
    }
    j = l
  } else {
    for (let i = length - 1; i >= 0; i--) {
      if (index > this.newlines[i]) {
        j = i
        break
      }
    }
  }

  if (j >= 0) {
    line = j + 2
    column = index - this.newlines[j]
  }

  return {
    column,
    line,
    offset: index,
  }
}

function getDirectQueryHook(
  callExpression: TSESTree.CallExpression,
): string | undefined {
  if (
    callExpression.callee.type !== AST_NODE_TYPES.Identifier ||
    !allHookNames.includes(callExpression.callee.name) ||
    !helpers.isTanstackQueryImport(callExpression.callee)
  ) {
    return undefined
  }

  if (
    (callExpression.callee.name === 'useQueries' ||
      callExpression.callee.name === 'useSuspenseQueries') &&
    hasCombineProperty(callExpression)
  ) {
    return undefined
  }

  return callExpression.callee.name
}

export function posToNumber(source: string, pos: number | Pos): number {
  if (typeof pos === 'number') return pos
  const lines = source.split(splitRE)
  const { line, column } = pos
  let start = 0
  for (let i = 0; i < line - 1 && i < lines.length; i++) {
    start += lines[i].length
    start += lineTerminatorLengthAt(source, start)
  }
  return start + column
}

