private fun inetSelfConnect(): Boolean {
    val localAddress = if (java7NetworkApisAvailable) {
        channel.localAddress
    } else {
        channel.socket().localSocketAddress
    }
    val remoteAddress = if (java7NetworkApisAvailable) {
        channel.remoteAddress
    } else {
        channel.socket().remoteSocketAddress
    }

    if (localAddress == null || remoteAddress == null) {
        throw IllegalStateException("localAddress and remoteAddress should not be null.")
    }

    val localInetSocketAddress = localAddress as? java.net.InetSocketAddress
    val remoteInetSocketAddress = remoteAddress as? java.net.InetSocketAddress

    if (localInetSocketAddress == null && remoteInetSocketAddress == null) {
        return false
    }

    val localHostAddress = localInetSocketAddress?.address?.hostAddress ?: ""
    val remoteHostAddress = remoteInetSocketAddress?.address?.hostAddress ?: ""
    val isRemoteAnyLocalAddress = remoteInetSocketAddress?.address?.isAnyLocalAddress ?: false
    val localPort = localInetSocketAddress?.port
    val remotePort = remoteInetSocketAddress?.port

    return localPort == remotePort && (isRemoteAnyLocalAddress || localHostAddress == remoteHostAddress)
}

private fun parseDnsResponse(source: Source): DnsResponse? {
    if (source.exhausted()) return null
    val id = source.readShort().toInt() and 0xFFFF
    val flags = source.readShort().toInt() and 0xFFFF
    val rcode = flags and 0xF
    val qdCount = source.readShort().toInt() and 0xFFFF
    val anCount = source.readShort().toInt() and 0xFFFF
    source.readShort() // NSCOUNT
    source.readShort() // ARCOUNT

    repeat(qdCount) {
        skipDnsName(source)
        source.readShort() // QTYPE
        source.readShort() // QCLASS
    }

    if (rcode != 0) return DnsResponse(id, emptyList())

    val addresses = mutableListOf<String>()
    repeat(anCount) {
        skipDnsName(source)
        val type = source.readShort().toInt() and 0xFFFF
        val cls = source.readShort().toInt() and 0xFFFF
        source.readInt() // TTL
        val rdLength = source.readShort().toInt() and 0xFFFF
        when {
            cls != DNS_CLASS_IN.toInt() -> source.skip(rdLength.toLong())
            type == DNS_TYPE_A.toInt() && rdLength == 4 -> addresses += readIpv4(source)
            type == DNS_TYPE_AAAA.toInt() && rdLength == 16 -> addresses += readIpv6(source)
            else -> source.skip(rdLength.toLong())
        }
    }
    return DnsResponse(id, addresses)
}

