private suspend fun readCacheUnsafe(urlHex: String): Set<CachedResponseData> {
    val path = Path(directoryPath, urlHex)
    if (!fileSystem.exists(path)) return emptySet()

    return try {
        withContext(dispatcher) {
            fileSystem.source(path).buffered().use { input ->
                val requestsCount = input.readInt()
                buildSet {
                    repeat(requestsCount) { add(readCache(input)) }
                }
            }
        }
    } catch (cause: Exception) {
        LOGGER.trace { "Exception during cache lookup in a file: ${cause.stackTraceToString()}" }
        emptySet()
    }
}

private fun resumeRootWith(result: Result<TSubject>) {
    check(lastSuspensionIndex >= 0) { "No more continuations to resume" }
    val next = suspensions[lastSuspensionIndex]!!
    suspensions[lastSuspensionIndex--] = null

    // Dispatch only when the continuation's dispatcher requires it.
    // When already on the correct thread, resume unintercepted to avoid a second updateThreadContext call —
    // the incoming dispatch already applied the context.
    val toResume = when (val interceptor = next.context[ContinuationInterceptor]) {
        is CoroutineDispatcher -> if (interceptor.isDispatchNeeded(next.context)) next.intercepted() else next
        else -> next.intercepted()
    }

    when (val exception = result.exceptionOrNull()) {
        null -> toResume.resumeWith(result)

        else -> {
            val recoveredException = recoverStackTraceBridge(exception, next)
            toResume.resumeWithException(recoveredException)
        }
    }
}

private fun tryGenerateNonceFromChannel(length: Int): Any? {
    if (length == NONCE_SIZE_IN_CHARS) {
        return nonceChannel.tryReceive().getOrNull()
    }
    val builder = StringBuilder(length)
    while (true) {
        val nonce = nonceChannel.tryReceive().getOrNull()
            ?: return builder
        builder.append(nonce, 0, (length - builder.length).coerceAtMost(nonce.length))
        if (builder.length == length) {
            return builder.toString()
        }
    }
}

private fun fillPlaceholder(index: Int, element: E): Core<E>? {
    val old = array.get(index and mask)
    /*
     * addLast actions:
     * 1) Commit tail slot
     * 2) Write element to array slot
     * 3) Check for array copy
     *
     * If copy happened between 2 and 3 then the consumer might have consumed our element,
     * then another producer might have written its placeholder in our slot, so we should
     * perform *unique* check that current placeholder is our to avoid overwriting another producer placeholder
     */
    if (old is Placeholder && old.index == index) {
        array.set(index and mask, element)
        // we've corrected missing element, should check if that propagated to further copies, just in case
        return this
    }
    // it is Ok, no need for further action
    return null
}

