private suspend fun drainTaskQueue(api: CurlMultiApiHandler) {
    while (true) {
        val task = if (api.hasHandlers()) {
            taskQueue.tryReceive()
        } else {
            taskQueue.receiveCatching()
        }.getOrNull() ?: break

        when (task) {
            is SendRequest -> handleSendRequest(api, task)

            is SendWebSocketFrame ->
                api.sendWebSocketFrame(task.websocket, task.flags, task.data, task.completionHandler)

            is CancelWebSocket ->
                api.cancelWebSocket(task.websocket, CancellationException("WebSocket session closed"))
        }
    }
}

private fun <T : Any> build(
    resultList: MutableList<Node<T>>,
    from: List<T>,
    maxLength: Int,
    idx: Int,
    length: (T) -> Int,
    charAt: (T, Int) -> Char
) {
    from.groupBy { charAt(it, idx) }.forEach { (ch, list) ->
        val nextIdx = idx + 1
        val children = ArrayList<Node<T>>()
        build(children, list.filter { length(it) > nextIdx }, maxLength, nextIdx, length, charAt)
        children.trimToSize()
        resultList.add(Node(ch, list.filter { length(it) == nextIdx }, children))
    }
}

