private suspend fun loop() {
    if (channel.availableForRead == 0) {
        awaitReady()
        output.flush()
    }

    var copied = 0L
    while (!channel.isClosedForRead) {
        channel.read { buffer, start, end ->
            val rc = end - start
            copied += rc
            if (copied > MAX_COPY_SIZE) {
                copied = 0
                yield()
            }

            awaitReady()
            output.write(buffer, start, rc)
            awaitReady()
            rc
        }
        if (channel.availableForRead == 0) output.flush()
    }
}

public fun String.isQuoted(): Boolean {
    if (length < 2) {
        return false
    }
    if (first() != '"' || last() != '"') {
        return false
    }
    var startIndex = 1
    do {
        val index = indexOf('"', startIndex)
        if (index == lastIndex) {
            break
        }

        var slashesCount = 0
        var slashIndex = index - 1
        while (this[slashIndex] == '\\') {
            slashesCount++
            slashIndex--
        }
        if (slashesCount % 2 == 0) {
            return false
        }

        startIndex = index + 1
    } while (startIndex < length)

    return true
}

