public fun skipKnownProxies(hosts: List<String>) {
    extractEdgeProxy { connectionPoint, headers ->
        val forValues = headers.forHeader?.split(',')

        var proxiesCount = 0
        while (
            hosts.lastIndex >= proxiesCount &&
            forValues != null &&
            forValues.lastIndex >= proxiesCount &&
            hosts[hosts.size - proxiesCount - 1].trim() == forValues[forValues.size - proxiesCount - 1].trim()
        ) {
            proxiesCount++
        }
        setValues(connectionPoint, headers) { values ->
            values.getOrElse(values.size - proxiesCount - 1) { values.lastOrNull() }?.trim()
        }
    }
}

private fun matchesPattern(
    pathSegments: List<String>,
    patternSegments: List<String>,
    pathIndex: Int = 0,
    patternIndex: Int = 0,
): Boolean {
    if (patternIndex == patternSegments.size) return pathIndex == pathSegments.size
    if (patternSegments[patternIndex] == "**") {
        var nextPatternIndex = patternIndex + 1
        while (nextPatternIndex < patternSegments.size && patternSegments[nextPatternIndex] == "**") {
            nextPatternIndex++
        }
        if (nextPatternIndex == patternSegments.size) return true

        for (candidatePathIndex in pathIndex until pathSegments.size) {
            if (pathSegments[candidatePathIndex] == patternSegments[nextPatternIndex] &&
                matchesPattern(pathSegments, patternSegments, candidatePathIndex + 1, nextPatternIndex + 1)
            ) {
                return true
            }
        }
        return false
    }
    return pathIndex < pathSegments.size &&
        pathSegments[pathIndex] == patternSegments[patternIndex] &&
        matchesPattern(pathSegments, patternSegments, pathIndex + 1, patternIndex + 1)
}

internal fun contentTypeAny(parentSymbol: IrSymbol): LocalReference? {
    val contentTypeClass: IrClassSymbol = context.referenceClass(contentTypeClass)
        ?: error("ContentType class not found")
    val companionObj = contentTypeClass.owner.companionObject()
        ?: error("ContentType companion object not found")
    val anyPropertyGetter = companionObj.properties.firstOrNull { it.name.asString() == "Any" }?.getter?.symbol
        ?: error("Property 'Any' not found on ContentType.Companion")
    val builder = DeclarationIrBuilder(context, parentSymbol)
    val callToProperty = builder.irCall(anyPropertyGetter).apply {
        dispatchReceiver = builder.irGetObject(companionObj.symbol)
    }

    return LocalReference.of(callToProperty)
}

suspend fun refreshTokenIfNeeded(
    call: HttpClientCall,
    provider: AuthProvider,
    request: HttpRequestBuilder
): Boolean {
    val tokenVersion = tokenVersions.computeIfAbsent(provider) { AtomicCounter() }
    val requestTokenVersions = request.attributes
        .computeIfAbsent(tokenVersionsAttributeKey) { mutableMapOf() }
    val requestTokenVersion = requestTokenVersions[provider]

    if (requestTokenVersion != null && requestTokenVersion >= tokenVersion.atomic.value) {
        LOGGER.trace { "Refreshing token for ${call.request.url}" }
        if (!provider.refreshToken(call.response)) {
            LOGGER.trace { "Refreshing token failed for ${call.request.url}" }
            return false
        } else {
            requestTokenVersions[provider] = tokenVersion.atomic.incrementAndGet()
        }
    }
    return true
}

