override suspend fun deserialize(charset: Charset, typeInfo: TypeInfo, content: Frame): Any? {
    if (!isApplicable(content)) {
        throw WebsocketConverterNotFoundException("Unsupported frame ${content.frameType.name}")
    }
    if (gson.isExcluded(typeInfo.type)) {
        throw ExcludedTypeGsonException(typeInfo.type)
    }

    try {
        return withContext(Dispatchers.IO) {
            val reader = content.readBytes().inputStream().reader(charset)
            gson.fromJson(reader, typeInfo.reifiedType)
        }
    } catch (cause: JsonSyntaxException) {
        throw JsonConvertException("Illegal json parameter found: ${cause.message}", cause)
    }
}

internal suspend fun SeekableByteChannel.writeToScope(
    writerScope: WriterScope,
    start: Long,
    endInclusive: Long
) {
    if (start > 0) {
        position(start)
    }

    if (endInclusive == -1L) {
        writerScope.channel.writeWhile { buffer ->
            val rc = read(buffer)
            rc != -1
        }

        return
    }

    var position = start
    writerScope.channel.writeWhile { buffer ->
        val fileRemaining = endInclusive - position + 1
        val rc = if (fileRemaining < buffer.remaining()) {
            val l = buffer.limit()
            buffer.limit(buffer.position() + fileRemaining.toInt())
            val r = read(buffer)
            buffer.limit(l)
            r
        } else {
            read(buffer)
        }

        if (rc > 0) position += rc

        rc != -1 && position <= endInclusive
    }
}

private fun Sink.subjectAlternativeNames(
    domains: List<String>,
    ipAddresses: List<InetAddress>
) {
    writeDerSequence {
        writeDerObjectIdentifier(OID.SubjectAltName)
        writeDerOctetString {
            writeDerSequence {
                for (domain in domains) {
                    writeX509Extension(2) {
                        // DNSName
                        writeFully(domain.toByteArray())
                    }
                }
                for (ip in ipAddresses) {
                    writeX509Extension(7) {
                        // IP address
                        writeFully(ip.address)
                    }
                }
            }
        }
    }
}

public inline fun <reified T> removeFirstIfIsInstanceOfOrPeekIf(predicate: (T) -> Boolean): T? {
    while (true) { // try to linearize
        val first = next as Node
        if (first === this) return null
        if (first !is T) return null
        if (predicate(first)) return first // just peek when predicate is true
        if (first.remove()) return first
        first.helpDelete() // must help delete, or loose lock-freedom
    }
}

