void _endStream(Http2StreamImpl stream) {
  if (stream.state == StreamState.Open) {
    _changeState(stream, StreamState.HalfClosedLocal);
  } else if (stream.state == StreamState.HalfClosedRemote) {
    _changeState(stream, StreamState.Closed);
  } else {
    throw StateError('Invalid state transition. This should never happen.');
  }
}

void _innerListen(MessageEvent event) {
  // Event data will be ArrayBuffer, Blob, or String.
  final eventData = event.data;
  final Object? data;
  if (eventData.typeofEquals('string')) {
    data = (eventData as JSString).toDart;
  } else if (eventData.typeofEquals('object') &&
      (eventData as JSObject).instanceOfString('ArrayBuffer')) {
    data = (eventData as JSArrayBuffer).toDart.asUint8List();
  } else {
    // Blobs are passed directly.
    data = eventData;
  }
  _controller.local.sink.add(data);
}

void _startClose(_PooledConnection pooled) {
  final connection = pooled.value;
  final done =
      connection != null
          ? connection.finish()
          : pooled.creation.then((c) => c.finish());
  final tracked = done.then<void>((_) {}).catchError((Object _) {});
  _pendingCloses.add(tracked);
  unawaited(tracked.whenComplete(() => _pendingCloses.remove(tracked)));
}

List<int> viewOrSublist(List<int> data, int offset, int length) {
  if (data is Uint8List) {
    return Uint8List.view(data.buffer, data.offsetInBytes + offset, length);
  } else {
    return data.sublist(offset, offset + length);
  }
}

void onTerminated(Object? error) {
  _toBeAcknowledgedSettings.clear();
  for (var completer in _toBeAcknowledgedCompleters) {
    completer.completeError(error!);
  }
}

void terminate(Object error) {
  if (!terminated) {
    result.addError(error);
    result.close();
    subscription.cancel();
  }
  terminated = true;
}

