void insertNewStreamMessageQueue(int streamId, StreamMessageQueueIn mq) {
  if (_stream2messageQueue.containsKey(streamId)) {
    throw ArgumentError(
      'Cannot register a SteramMessageQueueIn for the same streamId '
      'multiple times',
    );
