String toString() {
  final buffer = StringBuffer()
    ..write(type)
    ..write('/')
    ..write(subtype);

  parameters.forEach((attribute, value) {
    buffer.write('; $attribute=');
    if (nonToken.hasMatch(value)) {
      buffer
        ..write('"')
        ..write(
            value.replaceAllMapped(_escapedChar, (match) => '\\${match[0]}'))
        ..write('"');
    } else {
      buffer.write(value);
