void writeValue(int value, int numBits) {
  var i = numBits - 1;
  while (i >= 0) {
    if (currentBitOffset == 7 && i >= 7) {
      assert(currentByte == 0);

      buffer.addByte((value >> (i - 7)) & 0xff);
      currentBitOffset = 7;
      currentByte = 0;
      i -= 8;
    } else {
      currentByte |= ((value >> i) & 1) << currentBitOffset;

      currentBitOffset--;
      if (currentBitOffset == -1) {
        buffer.addByte(currentByte);
        currentBitOffset = 7;
        currentByte = 0;
      }
      i--;
    }
  }
}

