public func connect(to address: SocketAddress, promise: EventLoopPromise<Void>?) {
    let promise = promise ?? self.testingEventLoop.makePromise()
    promise.futureResult.whenSuccess {
        self.remoteAddress = address
    }
    if self.eventLoop.inEventLoop {
        self.pipeline.connect(to: address, promise: promise)
    } else {
        self.eventLoop.execute {
            self.pipeline.connect(to: address, promise: promise)
        }
    }
}

func reallocStorage(capacity minimumNeededCapacity: _Capacity) {
    let newCapacity = minimumNeededCapacity.nextPowerOf2ClampedToMax()
    let ptr = self.allocator.reallocate(self.bytes, size_t(self.capacity), size_t(newCapacity))!
    // bind the memory so we can assume it elsewhere to be bound to UInt8
    ptr.bindMemory(to: UInt8.self, capacity: Int(newCapacity))
    self._bytes = ptr
    self._capacity = newCapacity
}

func readExtendedAttribute(named name: String) -> Result<[UInt8], Errno> {
    // Required capacity is returned if a no buffer is passed to fgetxattr.
    self.getExtendedAttribute(named: name, buffer: nil).flatMap { capacity in
        guard capacity > 0 else {
            // Required capacity is zero: no values to read.
            return .success([])
        }

        // Read and decode.
        var buffer = [UInt8](repeating: 0, count: capacity)
        return buffer.withUnsafeMutableBytes { bytes in
            self.getExtendedAttribute(named: name, buffer: bytes)
        }.map { size in
            // Remove any trailing zeros.
            buffer.removeLast(buffer.count - size)
            return buffer
        }
    }
}

