private func dequeueWrites() {
    assert(!self.queuedWrites.isEmpty, "This must be called with a non empty queue")
    // `queuedWrites` is only ever non-empty if we have a delivery function.
    let deliverQueuedWrite = self.deliverQueuedWrite!
    repeat {
        // `self.decoder` is only `nil` whilst we're on the stack and this is only called when we're not.
        deliverQueuedWrite(&self.decoder!, self.queuedWrites.removeFirst())
    } while self.queuedWrites.count > 0
}

mutating func _heapRootify(index: Int, key: Element) {
    var index = index
    if self.comparator(self._storage[index], key) {
        fatalError("New key must be closer to the root than current key")
    }

    self._storage[index] = key
    while index > 0 && self.comparator(self._storage[index], self._storage[self.parentIndex(index)]) {
        self._storage.swapAt(index, self.parentIndex(index))
        index = self.parentIndex(index)
    }
}

func copySocketAddress(_ target: UnsafeMutablePointer<sockaddr_storage>) -> socklen_t {
    let erased = UnsafeMutableRawPointer(target)

    switch self.address {
    case .none:
        preconditionFailure("copySocketAddress called on write that has no address")
    case .v4(let innerAddress):
        erased.storeBytes(of: innerAddress.address, as: sockaddr_in.self)
        return socklen_t(MemoryLayout.size(ofValue: innerAddress.address))
    case .v6(let innerAddress):
        erased.storeBytes(of: innerAddress.address, as: sockaddr_in6.self)
        return socklen_t(MemoryLayout.size(ofValue: innerAddress.address))
    case .unixDomainSocket:
        fatalError("UDS with datagrams is currently not supported")
    }
}

