func accept(setNonBlocking: Bool = false) throws -> Socket? {
    try withUnsafeHandle { fd in
        #if os(Linux)
        let flags: Int32
        if setNonBlocking {
            flags = Linux.SOCK_NONBLOCK
        } else {
            flags = 0
        }
        let result = try Linux.accept4(descriptor: fd, addr: nil, len: nil, flags: flags)
        #else
        let result = try NIOBSDSocket.accept(socket: fd, address: nil, address_len: nil)
        #endif

        guard let fd = result else {
            return nil
        }

        let sock = try Socket(socket: fd)

        #if !os(Linux)
        if setNonBlocking {
            do {
                try sock.setNonBlocking()
            } catch {
                // best effort
                try? sock.close()
                throw error
            }
        }
        #endif
        return sock
    }
}

public func measure(_ fn: () throws -> Int) rethrows -> [Double] {
    func measureOne(_ fn: () throws -> Int) rethrows -> Double {
        let start = DispatchTime.now().uptimeNanoseconds
        _ = try fn()
        let end = DispatchTime.now().uptimeNanoseconds
        return Double(end - start) / Double(TimeAmount.seconds(1).nanoseconds)
    }

    _ = try measureOne(fn)  // pre-heat and throw away
    var measurements = Array(repeating: 0.0, count: 10)
    for i in 0..<10 {
        measurements[i] = try measureOne(fn)
    }

    return measurements
}

private func handleOversizeMessage(message: InboundIn) -> HTTPResponseHead {
    var payloadTooLargeHead = HTTPResponseHead(
        version: self.fullMessageHead?.version ?? .http1_1,
        status: .payloadTooLarge,
        headers: HTTPHeaders([("content-length", "0")])
    )

    switch message {
    case .head(let request):
        if !request.isKeepAlive {
            // If keep-alive is off and, no need to leave the connection open.
            // Send back a 413 and close the connection.
            payloadTooLargeHead.headers.add(name: "connection", value: "close")
        }
    default:
        // The client started to send data already, close because it's impossible to recover.
        // Send back a 413 and close the connection.
        payloadTooLargeHead.headers.add(name: "connection", value: "close")
    }

    return payloadTooLargeHead
}

private func _submit(id: Int?, _ body: @escaping WorkItem) {
    let submitted = self._workAvailable.withLock {
        let submitted: Bool

        switch self._state {
        case .running(var items):
            self._state = .modifying
            items.append(.init(workItem: body, id: id))
            self._state = .running(items)
            submitted = true

        case .shuttingDown, .stopped:
            submitted = false

        case .modifying:
            fatalError(".modifying state misuse")
        }

        return (workDelta: submitted ? 1 : 0, signal: submitted ? .signalOne : .none, result: submitted)
    }

    // if item couldn't be added run it immediately indicating that it couldn't be run
    if !submitted {
        body(.cancelled)
    }
}

public mutating func write(contentsOf bytes: some Sequence<UInt8>) async throws -> Int64 {
    let bufferSize = Int64(self.buffer.count)
    self.buffer.append(contentsOf: bytes)
    let bytesWritten = Int64(self.buffer.count) &- bufferSize

    if self.buffer.count >= self.capacity {
        try await self.flush()
    }

    return bytesWritten
}

@discardableResult public mutating func discardReadBytes() -> Bool {
    guard self._readerIndex > 0 else {
        return false
    }

    if self._readerIndex == self._writerIndex {
        // If the whole buffer was consumed we can just reset the readerIndex and writerIndex to 0 and move on.
        self._moveWriterIndex(to: 0)
        self._moveReaderIndex(to: 0)
        return true
    }

    if isKnownUniquelyReferenced(&self._storage) {
        self._storage.bytes.advanced(by: Int(self._slice.lowerBound))
            .copyMemory(
                from: self._storage.bytes.advanced(by: Int(self._slice.lowerBound + self._readerIndex)),
                byteCount: self.readableBytes
            )
        let indexShift = self._readerIndex
        self._moveReaderIndex(to: 0)
        self._moveWriterIndex(to: self._writerIndex - indexShift)
    } else {
        self._copyStorageAndRebase(extraCapacity: 0, resetIndices: true)
    }
    return true
}

