mutating func decode(buffer: inout ByteBuffer, hasReceivedLastChunk: Bool) throws -> InboundOut? {
    while true {
        guard
            let (slice, separator) = try self.splitDecoder.decode(
                buffer: &buffer,
                hasReceivedLastChunk: hasReceivedLastChunk
            )
        else {
            return nil
        }

        // If we are getting rid of empty subsequences then it doesn't matter if we detect
        // \r\n as a CR-LF, or as a CR + a LF. The backing decoder gets rid of the empty subsequence
        // anyway. Therefore, we can return early right here and skip the rest of the logic.
        if self.splitDecoder.omittingEmptySubsequences {
            return slice
        }

        // "\r\n" is 2 bytes long, so we need to manually account for it.
        switch separator {
        case UInt8(ascii: "\n") where slice.readableBytes == 0:
            let isCRLF = self.previousSeparatorWasCR
            self.previousSeparatorWasCR = false
            if isCRLF {
                continue
            }
        case UInt8(ascii: "\r"):
            self.previousSeparatorWasCR = true
        default:
            self.previousSeparatorWasCR = false
        }

        return slice
    }
}

private func onNextBatch(_ entries: [DirectoryEntry]) {
    let source = self.state.withLockedValue { state in
        state.sequenceProducerSource
    }

    guard let source else {
        assertionFailure("unexpectedly missing source")
        return
    }

    // No entries were read: this must be the end (as the batch size must be greater than zero).
    if entries.isEmpty {
        source.finish()
        self.clearSource()
        return
    }

    // Reading short means reading EOF. The enumerator closes itself in that case.
    let readEOF = entries.count < self.entriesPerBatch

    // Entries were produced: yield them and maybe produce more.
    let writeResult = source.yield(contentsOf: CollectionOfOne(entries))

    // Exit early if EOF was read; no use in trying to produce more.
    if readEOF {
        source.finish()
        self.clearSource()
        return
    }

    switch writeResult {
    case .produceMore:
        self.produceMore()
    case .stopProducing:
        self.pauseProducing()
    case .dropped:
        // The source is finished; mark ourselves as done.
        self.close()
    }
}

