func triggerAppropriateWriteOperations(
    scalarWriteOperation: (
        UnsafeRawBufferPointer, UnsafePointer<sockaddr>?, socklen_t, AddressedEnvelope<ByteBuffer>.Metadata?
    ) throws -> IOResult<Int>,
    vectorWriteOperation: (UnsafeMutableBufferPointer<MMsgHdr>) throws -> IOResult<Int>
) throws -> OverallWriteResult {
    try self.triggerWriteOperations { writeMechanism in
        switch writeMechanism {
        case .scalarBufferWrite:
            return try triggerScalarBufferWrite(scalarWriteOperation: { try scalarWriteOperation($0, $1, $2, $3) })
        case .vectorBufferWrite:
            do {
                return try triggerVectorBufferWrite(vectorWriteOperation: { try vectorWriteOperation($0) })
            } catch {
                // If the error we just hit is recoverable, we fall back to single write mode to
                // isolate exactly which write triggered the problem.
                guard error.isRecoverable else {
                    throw error
                }

                return try triggerScalarBufferWrite(scalarWriteOperation: {
                    try scalarWriteOperation($0, $1, $2, $3)
                })
            }
        case .scalarFileWrite:
            preconditionFailure("PendingDatagramWritesManager was handed a file write")
        case .nothingToBeWritten:
            assertionFailure("called \(#function) with nothing available to be written")
            return OneWriteOperationResult.writtenCompletely
        }
    }
}

fileprivate func multipliedSaturating(by other: Int64) -> Int64 {
    let (result, overflow) = self.multipliedReportingOverflow(by: other)
    guard overflow else {
        return result
    }
    // On overflow the sign of the true product is the product of the operand
    // signs, which holds for any multiplier rather than only the positive
    // constants used above.
    return (self < 0) == (other < 0) ? .max : .min
}

private mutating func parse(lines: some Sequence<String>) -> [WeightedStack] {
    for line in lines {
        loop: while true {
            switch self.parseNextState(line) {
            case .parsedStack(let stack, let count):
                self.stacks.append(WeightedStack(stack: stack, allocations: count))

            case .needsNextLine:
                break loop
            }
        }
    }

    return self.stacks
}

public func channelRead(context: ChannelHandlerContext, data: NIOAny) {
    let msg = NIOHTTPClientResponseAggregator.unwrapInboundIn(data)

    do {
        switch msg {
        case .head(let httpHead):
            try self.state.messageHeadReceived()
            try self.beginAggregation(context: context, response: httpHead)
        case .body(var content):
            try self.state.messageBodyReceived()
            try self.aggregate(context: context, content: &content)
        case .end(let trailingHeaders):
            try self.state.messageEndReceived()
            self.endAggregation(context: context, trailingHeaders: trailingHeaders)
        }
    } catch let error as NIOHTTPObjectAggregatorError {
        context.fireErrorCaught(error)
        // Won't be able to complete those
        self.fullMessageHead = nil
        self.buffer.clear()
    } catch let error {
        context.fireErrorCaught(error)
    }
}

