    let handle = try await self.threadPool.runIfActive { [sendableView] in
        let handle = try sendableView._open(
            atPath: path.underlying,
            mode: .readWrite,
            options: opts,
            permissions: perms,
            transactionalIfPossible: options.newFile?.transactionalCreation ?? false
        ).get()
        // Okay to transfer: we just created it and are now moving back to the callers task.
        return UnsafeTransfer(handle)
    }
    return handle.wrappedValue
}

public static func makeEmptyBox<NonOptionalValue>(
    valueType: NonOptionalValue.Type = NonOptionalValue.self,
    eventLoop: EventLoop
) -> NIOLoopBoundBox<Value> where NonOptionalValue? == Value {
    // Here, we -- possibly surprisingly -- do not precondition being on the EventLoop. This is okay for a few
    // reasons:
    // - We write the `Optional.none` value which we know is _not_ a value of the potentially non-Sendable type
    //   `Value`.
    // - Because of Swift's Definitive Initialisation (DI), we know that we did write `self._value` before `init`
    //   returns.
    // - The only way to ever write (or read indeed) `self._value` is by proving to be inside the `EventLoop`.
    .init(_value: nil, uncheckedEventLoop: eventLoop)
}

internal func syscall<T>(
    where function: String = #function,
    _ body: () throws -> UnsafeMutablePointer<T>?
)
    throws -> UnsafeMutablePointer<T>
{
    while true {
        if let res = try body() {
            return res
        } else {
            let err = errno
            switch err {
            case EINTR:
                continue
            default:
                preconditionIsNotUnacceptableErrno(err: err, where: function)
                throw IOError(errnoCode: err, reason: function)
            }
        }
    }
}

