public func optionalValueOrErrno<R>(
    retryOnInterrupt: Bool = true,
    _ fn: () -> R?
) -> Result<R?, Errno> {
    while true {
        Errno.clear()
        if let result = fn() {
            return .success(result)
        } else {
            let errno = Errno._current
            if errno == .interrupted, retryOnInterrupt {
                continue
            } else if errno.rawValue == 0 {
                return .success(nil)
            } else {
                return .failure(errno)
            }
        }
    }
}

fileprivate func decodeStringValidatingASCII() -> String? {
    var bytesIterator = self.makeIterator()
    var scalars: [Unicode.Scalar] = []
    scalars.reserveCapacity(self.underestimatedCount)
    var decoder = Unicode.ASCII.Parser()
    decode: while true {
        switch decoder.parseScalar(from: &bytesIterator) {
        case .valid(let v):
            scalars.append(Unicode.Scalar(v[0]))
        case .emptyInput:
            break decode
        case .error:
            return nil
        }
    }
    return String(scalars.map(Character.init))
}

