}

static func encode(alphabet: [UInt8], firstByte: UInt8, secondByte: UInt8?) -> UInt8 {
    var index = (firstByte & 0b00000011) << 4
    if let secondByte = secondByte {
        index += (secondByte & 0b11110000) >> 4
    }
    return alphabet[Int(index)]
}

