private func triggerScalarFileWrite(
    _ operation: (CInt, Int, Int) throws -> IOResult<Int>
) throws -> OneWriteOperationResult {
    assert(
        self.state.isFlushPending && !self.state.isEmpty && self.isOpen,
        "single write called in illegal state: flush pending: \(self.state.isFlushPending), empty: \(self.state.isEmpty), isOpen: \(self.isOpen)"
    )

    switch self.state[0].data {
    case .fileRegion(let file):
        let readerIndex = file.readerIndex
        let endIndex = file.endIndex
        let writeResult = try file.fileHandle.withUnsafeFileDescriptor { fd in
            try operation(fd, readerIndex, endIndex)
        }
        return self.didWrite(itemCount: 1, result: writeResult)
    case .byteBuffer:
        preconditionFailure("called \(#function) but first item to write was a ByteBuffer")
    }
}

func run(_ fn: @escaping () async -> Int) {
    let group = DispatchGroup()
    group.enter()
    Task {
        _ = await fn()
        group.leave()
    }
    group.wait()
}

private boolean isExcludedByStrategy(Field field, boolean serialize) {
  List<ExclusionStrategy> list = serialize ? serializationStrategies : deserializationStrategies;
  if (list.isEmpty()) {
    return false;
  }
  FieldAttributes fieldAttributes = new FieldAttributes(field);
  for (ExclusionStrategy exclusionStrategy : list) {
    if (exclusionStrategy.shouldSkipField(fieldAttributes)) {
      return true;
    }
  }
  return false;
}

private static int extractBeginningInt(String javaVersion) {
  try {
    StringBuilder num = new StringBuilder();
    for (int i = 0; i < javaVersion.length(); ++i) {
      char c = javaVersion.charAt(i);
      if (Character.isDigit(c)) {
        num.append(c);
      } else {
        break;
      }
    }
    return Integer.parseInt(num.toString());
  } catch (NumberFormatException e) {
    return -1;
  }
}

private void put(JsonElement value) {
  if (pendingName != null) {
    if (!value.isJsonNull() || getSerializeNulls()) {
      JsonObject object = (JsonObject) peek();
      object.add(pendingName, value);
    }
    pendingName = null;
  } else if (stack.isEmpty()) {
    product = value;
  } else {
    JsonElement element = peek();
    if (element instanceof JsonArray) {
      ((JsonArray) element).add(value);
    } else {
      throw new IllegalStateException();
    }
  }
}

private static String getExpectedJson(Object obj) {
  Class<?> clazz = obj.getClass();
  if (Primitives.isWrapperType(Primitives.wrap(clazz))) {
    return obj.toString();
  } else if (obj.getClass().equals(String.class)) {
    return "\"" + obj.toString() + "\"";
  } else {
    // Try invoking a getExpectedJson() method if it exists
    try {
      Method method = clazz.getMethod("getExpectedJson");
      Object results = method.invoke(obj);
      return (String) results;
    } catch (ReflectiveOperationException e) {
      throw new RuntimeException(e);
    }
  }
}

public static Type[] getMapKeyAndValueTypes(Type context, Class<?> contextRawType) {
  /*
   * Work around a problem with the declaration of java.util.Properties. That
   * class should extend Hashtable<String, String>, but it's declared to
   * extend Hashtable<Object, Object>.
   */
  if (Properties.class.isAssignableFrom(contextRawType)) {
    return new Type[] {String.class, String.class};
  }

  Type mapType = getSupertype(context, contextRawType, Map.class);
  // TODO: strip wildcards?
  if (mapType instanceof ParameterizedType) {
    ParameterizedType mapParameterizedType = (ParameterizedType) mapType;
    return mapParameterizedType.getActualTypeArguments();
  }
  return new Type[] {Object.class, Object.class};
}

