public int hashCode() {
  if (value == null) {
    return 31;
  }
  // The conditions below parallel the structure of equals(Object). Unlike in equals, every
  // numeric branch must delegate to the same double-based hash: equals can consider primitives
  // from *different* branches equal (for example Integer 42 equals Double 42.0 and a lazily
  // parsed number 42 through the floating-point comparison), so a branch hashing anything other
  // than the double value would give equal primitives different hash codes, see
  // https://github.com/google/gson/issues/992
  if (isIntegral(this)) {
    // equals compares two integral primitives by their BigInteger values or long values;
    // primitives equal under either comparison also have the same double value, so the
    // double-based hash is consistent with this branch of equals. It is also consistent with
    // the mixed comparisons handled below, such as Integer 42 vs Double 42.0.
    return hashOfDoubleValue(getAsNumber().doubleValue());
  }
  if (value instanceof Number) {
    // equals compares the remaining numbers by their double values. (For two BigDecimals it
    // uses compareTo, which only considers values equal that also have the same double value.)
    return hashOfDoubleValue(getAsNumber().doubleValue());
  }
  return value.hashCode();
}

private void addUserDefinedAdapters(List<TypeAdapterFactory> all) {
  if (!this.factories.isEmpty()) {
    List<TypeAdapterFactory> reversedFactories = new ArrayList<>(this.factories);
    Collections.reverse(reversedFactories);
    all.addAll(reversedFactories);
  }

  if (!this.hierarchyFactories.isEmpty()) {
    List<TypeAdapterFactory> reversedHierarchyFactories =
        new ArrayList<>(this.hierarchyFactories);
    Collections.reverse(reversedHierarchyFactories);
    all.addAll(reversedHierarchyFactories);
  }
}

public static boolean requiresOwnerType(Type rawType) {
  if (rawType instanceof Class<?>) {
    Class<?> rawTypeAsClass = (Class<?>) rawType;
    return !Modifier.isStatic(rawTypeAsClass.getModifiers())
        && rawTypeAsClass.getDeclaringClass() != null;
  }
  return false;
}

private TypeAdapter<T> delegate() {
  TypeAdapter<T> delegate = this.delegate;
  if (delegate == null) {
    // Can occur when adapter is leaked to other thread or when adapter is used for
    // (de-)serialization
    // directly within the TypeAdapterFactory which requested it
    throw new IllegalStateException(
        "Adapter for type with cyclic dependency has been used"
            + " before dependency has been resolved");
  }
  return delegate;
}

public boolean isClassJsonAdapterFactory(TypeToken<?> type, TypeAdapterFactory factory) {
  Objects.requireNonNull(type);
  Objects.requireNonNull(factory);

  if (factory == TREE_TYPE_CLASS_DUMMY_FACTORY) {
    return true;
  }

  // Using raw type to match behavior of `create(Gson, TypeToken<T>)` above
  Class<?> rawType = type.getRawType();

  TypeAdapterFactory existingFactory = adapterFactoryMap.get(rawType);
  if (existingFactory != null) {
    return areSameFactories(existingFactory, factory);
  }

  // If no factory has been created for the type yet check manually for a @JsonAdapter annotation
  // which specifies a TypeAdapterFactory
  // Otherwise behavior would not be consistent, depending on whether or not adapter had been
  // requested before call to `isClassJsonAdapterFactory` was made
  JsonAdapter annotation = getAnnotation(rawType);
  if (annotation == null) {
    return false;
  }

  Class<?> adapterClass = annotation.value();
  if (!TypeAdapterFactory.class.isAssignableFrom(adapterClass)) {
    return false;
  }

  Object adapter = createAdapter(constructorConstructor, adapterClass);
  TypeAdapterFactory newFactory = (TypeAdapterFactory) adapter;
  newFactory = putFactoryAndGetCurrent(rawType, newFactory);

  return areSameFactories(newFactory, factory);
}

