public static function configureUnpooledPostgresConnection(Application $app): void
{
    $host = $app['config']->get('database.connections.pgsql.host', '');

    if (str_contains($host, 'pg.laravel.cloud') &&
        str_contains($host, '-pooler')) {
        $app['config']->set(
            'database.connections.pgsql-unpooled',
            array_merge($app['config']->get('database.connections.pgsql'), [
                'host' => str_replace('-pooler', '', $host),
            ])
        );

        $app['config']->set(
            'database.connections.pgsql.options.'.PDO::ATTR_EMULATE_PREPARES, true
        );
    }
}

public function many(array $keys)
{
    [$memoized, $retrieved, $missing] = [[], [], []];

    foreach ($keys as $key) {
        $prefixedKey = $this->prefix($key);

        if (array_key_exists($prefixedKey, $this->cache)) {
            $memoized[$key] = $this->cache[$prefixedKey];
        } else {
            $missing[] = $key;
        }
    }

    if ($missing !== []) {
        $retrieved = tap($this->repository->many($missing), function ($values) {
            foreach ($values as $key => $value) {
                $this->cache[$this->prefix($key)] = $value;
            }
        });
    }

    $result = [];

    foreach ($keys as $key) {
        if (array_key_exists($key, $memoized)) {
            $result[$key] = $memoized[$key];
        } else {
            $result[$key] = $retrieved[$key];
        }
    }

    return $result;
}

protected function decrypt(Request $request)
{
    foreach ($request->cookies as $key => $cookie) {
        if ($this->isDisabled($key)) {
            continue;
        }

        try {
            $value = $this->decryptCookie($key, $cookie);

            $request->cookies->set($key, $this->validateValue($key, $value));
        } catch (DecryptException) {
            $request->cookies->set($key, null);
        }
    }

    return $request;
}

