protected function handleMissingTranslationKey($key, $replace, $locale, $fallback)
{
    if (! $this->handleMissingTranslationKeys ||
        ! isset($this->missingTranslationKeyCallback)) {
        return $key;
    }

    // Prevent infinite loops...
    $this->handleMissingTranslationKeys = false;

    $key = call_user_func(
        $this->missingTranslationKeyCallback,
        $key, $replace, $locale, $fallback
    ) ?? $key;

    $this->handleMissingTranslationKeys = true;

    return $key;
}

public function pruneUnfinished(DateTimeInterface $before)
{
    $query = $this->connection->table($this->table)
        ->whereNull('finished_at')
        ->where('created_at', '<', $before->getTimestamp());

    $totalDeleted = 0;

    do {
        $deleted = $query->limit(1000)->delete();

        $totalDeleted += $deleted;
    } while ($deleted !== 0);

    return $totalDeleted;
}

public function __call($method, $parameters)
{
    return $this->collection->{$this->method}(function ($value) use ($method, $parameters) {
        return is_string($value)
            ? $value::{$method}(...$parameters)
            : $value->{$method}(...$parameters);
    });
}

protected function determineRouteCountOutput($routes, $terminalWidth)
{
    $routeCountText = 'Showing ['.$routes->count().'] routes';

    $offset = $terminalWidth - mb_strlen($routeCountText) - 2;

    $spaces = str_repeat(' ', $offset);

