    [$hash, $hashPrefix] = $this->getHash($value);

    return ! $this->search($hashPrefix)
        ->contains(function ($line) use ($hash, $hashPrefix, $threshold) {
            [$hashSuffix, $count] = explode(':', $line);

            return $hashPrefix.$hashSuffix === $hash && $count > $threshold;
        });
}

