public static function replaceStart($search, $replace, $subject)
{
    $search = (string) $search;

    if ($search === '') {
        return $subject;
    }

    if (static::startsWith($subject, $search)) {
        return static::replaceFirst($search, $replace, $subject);
    }

    return $subject;
}

