protected function registerValidationFactory()
{
    $this->app->singleton('validator', function ($app) {
        $validator = new Factory($app['translator'], $app);

        // The validation presence verifier is responsible for determining the existence of
        // values in a given data collection which is typically a relational database or
        // other persistent data stores. It is used to check for "uniqueness" as well.
        if (isset($app['db'], $app['validation.presence'])) {
            $validator->setPresenceVerifier($app['validation.presence']);
        }

        return $validator;
    });
}

protected function prepareMessage(Response $response)
{
    $message = "HTTP request returned status code {$response->status()}";

    $truncateExceptionsAt = $this->truncateExceptionsAt ?? static::$truncateAt;

    $psrResponse = $response->toPsrResponse();

    $summary = null;

    if (is_int($truncateExceptionsAt)) {
        $summary = Message::bodySummary($psrResponse, $truncateExceptionsAt);
    } elseif (($body = $psrResponse->getBody())->isSeekable() && $body->isReadable()) {
        $summary = Message::toString($psrResponse);
    }

    return is_null($summary) ? $message : $message.":\n{$summary}\n";
}

public function __call($method, $parameters)
{
    if (static::hasMacro($method)) {
        return $this->macroCall($method, $parameters);
    }

    if (str_starts_with($method, 'where')) {
        return $this->dynamicWhere($method, $parameters);
    }

    static::throwBadMethodCallException($method);
}

public function add($key, $value, $seconds)
{
    if (! is_null($this->get($key))) {
        return false;
    }

    $key = $this->prefix.$key;
    $value = $this->serialize($value);
    $expiration = $this->getTime() + $seconds;

    if (! $this->getConnection() instanceof SqlServerConnection) {
        return $this->table()->insertOrIgnore(['key' => $key, 'value' => $value, 'expiration' => $expiration]) > 0;
    }

    try {
        return $this->table()->insert(['key' => $key, 'value' => $value, 'expiration' => $expiration]);
    } catch (QueryException) {
        // ...
    }

    return false;
}

public function createSessionDriver($name, $config)
{
    $guard = new SessionGuard(
        $name,
        $this->createUserProvider($config['provider'] ?? null),
        $this->app['session.store'],
        rehashOnLogin: $this->app['config']->get('hashing.rehash_on_login', true),
        timeboxDuration: $this->app['config']->get('auth.timebox_duration', 200000),
        hashKey: $this->app['config']->get('app.key'),
    );

    // When using the remember me functionality of the authentication services we
    // will need to be set the encryption instance of the guard, which allows
    // secure, encrypted cookie values to get generated for those cookies.
    $guard->setCookieJar($this->app['cookie']);

    $guard->setDispatcher($this->app['events']);

    $guard->setRequest($this->app->refresh('request', $guard, 'setRequest'));

    if (isset($config['remember'])) {
        $guard->setRememberDuration($config['remember']);
    }

    return $guard;
}

public function retrieveByCredentials(#[\SensitiveParameter] array $credentials)
{
    $credentials = array_filter(
        $credentials,
        fn ($key) => ! str_contains($key, 'password'),
        ARRAY_FILTER_USE_KEY
    );

    if (empty($credentials)) {
        return;
    }

    // First we will add each credential element to the query as a where clause.
    // Then we can execute the query and, if we found a user, return it in a
    // Eloquent User "model" that will be utilized by the Guard instances.
    $query = $this->newModelQuery();

    foreach ($credentials as $key => $value) {
        if (is_array($value) || $value instanceof Arrayable) {
            $query->whereIn($key, $value);
        } elseif ($value instanceof Closure) {
            $value($query);
        } else {
            $query->where($key, $value);
        }
    }

    return $query->first();
}

protected function compileColumns(Builder $query, $columns)
{
    if (! is_null($query->aggregate)) {
        return;
    }

    $select = $query->distinct ? 'select distinct ' : 'select ';

    // If there is a limit on the query, but not an offset, we will add the top
    // clause to the query, which serves as a "limit" type clause within the
    // SQL Server system similar to the limit keywords available in MySQL.
    if (is_numeric($query->limit) && $query->limit > 0 && $query->offset <= 0) {
        $select .= 'top '.((int) $query->limit).' ';
    }

    return $select.$this->columnize($columns);
}

