protected function connectionString(array $versionInfo)
{
    $value = ' --user="${:LARAVEL_LOAD_USER}" --password="${:LARAVEL_LOAD_PASSWORD}"';

    $config = $this->connection->getConfig();

    $value .= $config['unix_socket'] ?? false
        ? ' --socket="${:LARAVEL_LOAD_SOCKET}"'
        : ' --host="${:LARAVEL_LOAD_HOST}" --port="${:LARAVEL_LOAD_PORT}"';

    if (isset($config['options'][Mysql::ATTR_SSL_CA])) {
        $value .= ' --ssl-ca="${:LARAVEL_LOAD_SSL_CA}"';
    }

    if (isset($config['options'][Mysql::ATTR_SSL_CERT])) {
        $value .= ' --ssl-cert="${:LARAVEL_LOAD_SSL_CERT}"';
    }

    if (isset($config['options'][Mysql::ATTR_SSL_KEY])) {
        $value .= ' --ssl-key="${:LARAVEL_LOAD_SSL_KEY}"';
    }

    /** @phpstan-ignore classConstant.notFound */
    if (($config['options'][Mysql::ATTR_SSL_VERIFY_SERVER_CERT] ?? null) === false) {
        if (version_compare($versionInfo['version'], '5.7.11', '>=') && ! $versionInfo['isMariaDb']) {
            $value .= ' --ssl-mode=DISABLED';
        } else {
            $value .= ' --ssl=off';
        }
    }

    return $value;
}

protected function unserialize($value)
{
    if (is_numeric($value)) {
        return $value;
    }

    if ($this->serializableClasses !== null) {
        return unserialize($value, ['allowed_classes' => $this->serializableClasses]);
    }

    return unserialize($value);
}

public static function withoutEvents(callable $callback)
{
    $dispatcher = static::getEventDispatcher();

    if ($dispatcher) {
        static::setEventDispatcher(new NullDispatcher($dispatcher));
    }

    try {
        return $callback();
    } finally {
        if ($dispatcher) {
            static::setEventDispatcher($dispatcher);
        }
    }
}

public function assertOnlyInvalid($errors = null, $errorBag = 'default', $responseKey = 'errors')
{
    if ($this->baseResponse->headers->get('Content-Type') === 'application/json') {
        return $this->assertOnlyJsonValidationErrors($errors, $responseKey);
    }

    $this->assertSessionHas('errors');

    $sessionErrors = $this->session()->get('errors')
        ->getBag($errorBag)
        ->getMessages();

    $expectedErrorKeys = (new Collection($errors))
        ->map(fn ($value, $key) => is_int($key) ? $value : $key)
        ->all();

    $unexpectedErrorKeys = Arr::except($sessionErrors, $expectedErrorKeys);

    PHPUnit::withResponse($this)->assertTrue(
        count($unexpectedErrorKeys) === 0,
        'Response has unexpected validation errors: '.(new Collection($unexpectedErrorKeys))->keys()->map(fn ($key) => "'{$key}'")->join(', ')
    );

    return $this;
}

public function statement($query, $bindings = [])
{
    return $this->run($query, $bindings, function ($query, $bindings) {
        if ($this->pretending()) {
            return true;
        }

        $statement = $this->getPdo()->prepare($query);

        $this->bindValues($statement, $this->prepareBindings($bindings));

        $this->recordsHaveBeenModified();

        return $statement->execute();
    });
}

